-- [SOURCE_QUALIFIER] Step: apply_SQ_DATA
SELECT  HSU.UNIT_ADDR_CODE AS UNIT_ADDR_CODE,
        CMM.HSE_SRVC_APLY_NUM AS HSE_SRVC_APLY_NUM,
        ODMS.CATG_USER_TYPE_CODE AS CATG_USER_TYPE_CODE,
        COUNT(DISTINCT CAM.CUST_MBR_ID_TYPE_CODE || CAM.CUST_MBR_ID_NUM) AS FMLY_SIZE_NUM,
        RASS.MIN_UNIT_HEAD_CNT AS MIN_UNIT_HEAD_CNT,
        RASS.MAX_UNIT_HEAD_CNT AS MAX_UNIT_HEAD_CNT,
        HSU.UNIT_IFA_AREA AS UNIT_IFA_AREA,
case when tams.tncy_agrmt_cmnc_date > add_months(to_date('$$v_rpt_mth'||'01','yyyymmdd'),1) - 1 then intk.rent_fctr_code
else (select max(rent_fctr_code) keep (dense_rank last order by bgn_date)
        from sor_ems_tam_tncy_agrmt_sts where tncy_agrmt_key=tam.tncy_agrmt_key
         and (to_date('$$v_snsh_date','yyyymmdd') > end_date or to_date('$$v_snsh_date','yyyymmdd') between bgn_date and end_date)
         and rent_bgn_date<=add_months(to_date('$$v_rpt_mth'||'01', 'yyyymmdd'),1) - 1)
end AS RENT_FCTR_CODE,
        INTK.RVS_INTK_DATE AS RVS_INTK_DATE,
        TAMS.PREV_CODE_ADDR AS PREV_CODE_ADDR
FROM    SOR_EMS_TAM_TNCY_AGRMT      TAM,
        SOR_EMS_TAM_TNCY_AGRMT_STS  TAMS,
        SOR_HSM_UNIT                HSU,
        SOR_HSM_BLK                 HSB,
        SOR_EMS_RFX_ALCT_STD        RAS,
        SOR_EMS_RFX_ALCT_STD_STS    RASS,
        (
        SELECT
            PHA.HSE_SRVC_APLY_KEY 
            , QCS.CATG_USER_TYPE_CODE
            , POS.OPR_TYPE_CODE
        FROM    
            (SELECT APLY_KEY, HSE_SRVC_APLY_KEY FROM SOR_EMS_PHA_APLY) PHA
            , (SELECT APLY_KEY, QTA_CATG_CODE, OPR_CODE FROM SOR_EMS_PHA_APLY_STS WHERE ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1) - 1 BETWEEN BGN_DATE AND END_DATE) PHS
            , (SELECT QTA_CATG_USER_KEY, QTA_CATG_CODE FROM SOR_EMS_REF_QTA_CATG_USER) QCU
            , (SELECT CATG_USER_TYPE_CODE, QTA_CATG_USER_KEY FROM SOR_EMS_REF_QTA_CATG_USER_STS WHERE ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1) - 1 BETWEEN BGN_DATE AND END_DATE AND QTA_CATG_TYPE_CODE = 'C') QCS
            , (SELECT OPR_KEY, OPR_CODE FROM SOR_EMS_POR_OPR) POR
            , (SELECT OPR_KEY, OPR_TYPE_CODE FROM SOR_EMS_POR_OPR_STS WHERE ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1) - 1 BETWEEN BGN_DATE AND END_DATE) POS
        WHERE
            PHA.APLY_KEY = PHS.APLY_KEY
            AND PHS.QTA_CATG_CODE = QCU.QTA_CATG_CODE
            AND QCU.QTA_CATG_USER_KEY = QCS.QTA_CATG_USER_KEY 
            AND POR.OPR_KEY = POS.OPR_KEY
            AND PHS.OPR_CODE = POR.OPR_CODE
        )   ODMS,
        (
        SELECT
            INTK.CUST_KEY
            , INTK.HSE_SRVC_APLY_KEY
            , INTK.ALCT_UNIT_KEY
            , INTK.RVS_INTK_DATE
            , RENT.RENT_FCTR_CODE
        FROM 
            (SELECT INTK.CUST_KEY, INTK.HSE_SRVC_APLY_KEY, INTK.ALCT_UNIT_KEY, INTS.RVS_INTK_DATE, INTS.RVS_RENT_FCTR_KEY FROM SOR_EMS_PAL_PRH_INTK_SCHD INTK, SOR_EMS_PAL_PRH_INTK_SCHD_STS INTS WHERE INTK.PRH_INTK_SCHD_KEY = INTS.PRH_INTK_SCHD_KEY AND INTS.INTK_SCHD_STS_CODE IN ('DC', 'OFACPT') AND ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1) - 1 BETWEEN INTS.BGN_DATE AND INTS.END_DATE) INTK
            , (SELECT RENT_FCTR_KEY, RENT_FCTR_CODE FROM SOR_EMS_SRF_RENT_FCTR_CODE) RENT
        WHERE
            INTK.RVS_RENT_FCTR_KEY = RENT.RENT_FCTR_KEY (+)
        )   INTK,
        SOR_EMS_CMM_HSE_SRVC_APLY_STS   CMM,
        SOR_EMS_CPM_CUST_APLY           CAP,
        SOR_EMS_CPM_CUST_APLY_MBR       CAM,
        SOR_EMS_CPM_CUST_APLY_MBR_STS   CAMS
WHERE   TAM.TNCY_AGRMT_KEY = TAMS.TNCY_AGRMT_KEY
AND     TAMS.UNIT_KEY = HSU.UNIT_KEY
AND     HSU.BLK_KEY = HSB.BLK_KEY
AND     RAS.ALCT_STD_KEY = RASS.ALCT_STD_KEY
AND     HSU.BLK_KEY = RAS.BLK_KEY 
AND     HSU.UNIT_IFA_AREA = RAS.UNIT_IFA_AREA 
AND     HSU.UNIT_TYPE_CODE = RAS.UNIT_TYPE_CODE
AND     TAM.HSE_SRVC_APLY_KEY = ODMS.HSE_SRVC_APLY_KEY
AND     TAM.CUST_KEY = INTK.CUST_KEY 
AND     TAM.HSE_SRVC_APLY_KEY = INTK.HSE_SRVC_APLY_KEY
AND     TAMS.UNIT_KEY = INTK.ALCT_UNIT_KEY
AND     CMM.HSE_SRVC_APLY_KEY = TAM.HSE_SRVC_APLY_KEY
--
AND     TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN TAMS.BGN_DATE AND TAMS.END_DATE
AND     ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1) - 1 BETWEEN RASS.BGN_DATE AND RASS.END_DATE
AND     ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1) - 1 BETWEEN CMM.BGN_DATE AND CMM.END_DATE
--
AND     NOT EXISTS (
        SELECT  NULL
        FROM    SOR_EMS_TAM_TNCY_AGRMT_STS  TAC
        WHERE   TAC.UNIT_KEY = TAMS.UNIT_KEY 
        AND     TAMS.TNCY_AGRMT_CMNC_DATE BETWEEN TAC.TNCY_AGRMT_TM_TRMT_DATE + 1 AND TAC.TNCY_AGRMT_TM_TRMT_DATE + 30
        AND     TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN TAC.BGN_DATE AND TAC.END_DATE)
AND     TAMS.TNCY_AGRMT_TM_STS_CODE IN ('P', 'I', 'A')
AND     RAS.UNIT_ALCT_STD_TYPE_CODE = 'O' 
--
AND     UPPER(UNIT_ADDR_CODE) LIKE 'E9%'
AND     TO_CHAR(INTK.RVS_INTK_DATE, 'YYYYMM') = '$$v_rpt_mth'
AND     CATG_USER_TYPE_CODE IS NOT NULL
--
AND     CAP.CUST_APLY_KEY = CAM.CUST_APLY_KEY
AND     CAM.CUST_APLY_MBR_KEY = CAMS.CUST_APLY_MBR_KEY
AND     CAMS.CUST_APLY_MBR_STS_CODE IN ('A', 'T')
AND     CAM.HSE_SRVC_APLY_TYPE_CODE = 'A'
AND     (CAMS.CUST_MBR_UP_IND = 'N'
OR       CAMS.CUST_MBR_UP_IND IS NULL)
AND     CAP.CUST_KEY = TAM.CUST_KEY
AND     CAP.HSE_SRVC_APLY_KEY = TAM.HSE_SRVC_APLY_KEY
AND     ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1) - 1 BETWEEN CAMS.BGN_DATE AND CAMS.END_DATE
--
GROUP BY
        SUBSTR(HSU.UNIT_ADDR_CODE, 2, 5),
        HSU.UNIT_ADDR_CODE,
        HSE_SRVC_APLY_NUM,
        CATG_USER_TYPE_CODE,
        RASS.MIN_UNIT_HEAD_CNT,
        RASS.MAX_UNIT_HEAD_CNT,
        HSU.UNIT_IFA_AREA,
        INTK.RENT_FCTR_CODE,
        RVS_INTK_DATE,
        TAMS.PREV_CODE_ADDR,
        tam.tncy_agrmt_key,
        tams.tncy_agrmt_cmnc_date
ORDER BY
        HSU.UNIT_ADDR_CODE;

