-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_HSM_UNIT
select
HSU.UNIT_KEY,
HSU.UNIT_ADDR_CODE,
est.est_key AS EST_KEY,
dch.EMMS_DSTR_KEY as EMMS_DTSR_CHC_DSTR_KEY,
dis.EMMS_DSTR_KEY as EMMS_DTSR_BRD_DSTR_KEY,
RFX.UNIT_TYPE_CODE,
RFX.UNIT_IFA_AREA,
RFXS.MAX_UNIT_HEAD_CNT,
RFXS.MIN_UNIT_HEAD_CNT
 from 
SOR_HSM_UNIT 	HSU,
--SOR_HSM_UNIT_STS 	HSUS,
SOR_EMS_RFX_ALCT_STD 	RFX,
SOR_EMS_RFX_ALCT_STD_STS RFXS,
sor_hsm_blk blk,
sor_hsm_est est,
sor_ems_hsm_prh_est_sts PRH,
(SELECT D.EMMS_DSTR_KEY, EDR.EST_KEY FROM SOR_HSM_DSTR D, SOR_HSM_EST_DSTR_RLTN EDR WHERE EDR.DSTR_KEY = D.DSTR_KEY AND DSTR_TYPE_CODE = 'DCH' AND LAST_DAY(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD')) BETWEEN BGN_DATE AND END_DATE) DCH,
(SELECT D.EMMS_DSTR_KEY, EDR.EST_KEY FROM SOR_HSM_DSTR D, SOR_HSM_EST_DSTR_RLTN EDR WHERE EDR.DSTR_KEY = D.DSTR_KEY AND DSTR_TYPE_CODE = 'DIS' AND LAST_DAY(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD')) BETWEEN BGN_DATE AND END_DATE) DIS
where 
--HSU.UNIT_KEY = HSUS.UNIT_KEY
--AND LAST_DAY(TO_DATE('$$v_rpt_mth' || '01','yyyymmdd')) between HSUS.bgn_date and HSUS.end_date
RFX.ALCT_STD_KEY =  RFXS.ALCT_STD_KEY
AND LAST_DAY(TO_DATE('$$v_rpt_mth' || '01','yyyymmdd')) between RFXS.bgn_date and RFXS.end_date
AND HSU.BLK_KEY = RFX.BLK_KEY 
AND HSU.UNIT_IFA_AREA= RFX.UNIT_IFA_AREA
AND HSU.UNIT_TYPE_CODE = RFX.UNIT_TYPE_CODE
and HSU.UNIT_ADDR_CODE not like 'E9%'
AND HSU.blk_key = blk.blk_key and 
blk.est_key = est.est_key and 
est.est_key = dch.est_key and
est.est_key = dis.est_key and 
PRH.EST_KEY = EST.EST_KEY and 
LAST_DAY(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD')) BETWEEN prh.BGN_DATE AND prh.END_DATE and 
RFX.UNIT_ALCT_STD_TYPE_CODE = 'O'
order by HSU.unit_key;

-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_WKM_MNR_WORK_DTL
SELECT 		HSU.UNIT_KEY,
					VWOS.WORK_ADDR_CODE,      
					WODS.WORK_ISS_DATE,
					VWOS.WORK_DRFT_ORD_ISS_DATE,
					VWOS.WORK_CMPLT_RPT_DATE,
					VWOS.WORK_CMPLT_CERT_DATE,
					VWO.WORK_ORD_NUM,
					VWOS.WORK_DTL_FRZ_DATE,
					VWOS.WORK_DTL_ACT_DATE,
					NVL(VWOS.WORK_VFRA_TYPE_CODE, 'BLANK'),
					VWOS.WORK_STS_CODE,
					WOD.WORK_VRTN_ORD_NUM,
					VWO.WORK_ORD_KEY,
					WOD.WORK_DTL_KEY
			FROM    SOR_WKM_MNR_WORK_ORD            VWO,
	                SOR_WKM_VAR_MNR_WORK_ORD_STS    VWOS,
	                SOR_WKM_MNR_WORK_DTL            WOD,
	                SOR_WKM_VAR_MNR_WORK_DTL_STS    WODS,
			SOR_HSM_UNIT			HSU
	        WHERE   VWO.WORK_ORD_KEY = VWOS.WORK_ORD_KEY
		AND	TRIM(HSU.UNIT_ADDR_CODE) = TRIM(VWOS.WORK_ADDR_CODE)
	        AND     TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN VWOS.BGN_DATE AND VWOS.END_DATE 
	        AND     VWO.WORK_ORD_KEY = WOD.WORK_ORD_KEY
	        AND     WOD.WORK_DTL_KEY = WODS.WORK_DTL_KEY
	        --AND     WOD.WORK_TYPE_CODE = 'VAR'
		AND WOD.WORK_VRTN_ORD_NUM = '00'
	        AND     TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN WODS.BGN_DATE AND WODS.END_DATE
ORDER BY HSU.UNIT_KEY;

-- [SELECT] Step: read_LKP_UNIT_VALID_MAX_DOT
-- Connection: DPA
select unit_key AS UNIT_KEY, 
max(TNCY_AGRMT_TM_TRMT_DATE) AS TNCY_AGRMT_TM_TRMT_DATE from
(
select 
unit_key as UNIT_KEY,
max(tncy_agrmt_tm_trmt_date) as TNCY_AGRMT_TM_TRMT_DATE
from 
sor_ems_tam_tncy_agrmt_sts
where tncy_agrmt_tm_sts_code in ('A','I')
AND TO_DATE('$$v_snsh_date','YYYYMMDD') BETWEEN BGN_DATE AND END_DATE
group by unit_key
union all
select
RM.unit_key as UNIT_KEY,
max(TAMS.tncy_agrmt_tm_trmt_date) as TNCY_AGRMT_TM_TRMT_DATE
from 
sor_ems_tam_tncy_agrmt_sts TAMS,
sor_ems_tam_adtn_room RM
where tncy_agrmt_tm_sts_code in ('A','I')
AND RM.TNCY_AGRMT_KEY = TAMS.TNCY_AGRMT_KEY
AND TO_DATE('$$v_snsh_date','YYYYMMDD') BETWEEN BGN_DATE AND END_DATE
group by RM.unit_key
) GROUP BY UNIT_KEY;

-- [SELECT] Step: read_LKP_FRZ_WO
-- Connection: DPA
SELECT 
	'F' AS FRZ_IND
	, VWOS.WORK_VFRA_TYPE_CODE AS WORK_VFRA_TYPE_CODE
	, VWO.WORK_ORD_KEY AS WORK_ORD_KEY
	, VWOS.BGN_DATE AS BGN_DATE
FROM    
	SOR_WKM_MNR_WORK_ORD VWO
	, SOR_WKM_VAR_MNR_WORK_ORD_STS VWOS
	, SOR_HSM_UNIT HSU
WHERE   
	VWO.WORK_ORD_KEY = VWOS.WORK_ORD_KEY
	AND	TRIM(HSU.UNIT_ADDR_CODE) = TRIM(VWOS.WORK_ADDR_CODE)
	AND WORK_STS_CODE = 'W0900' 
	AND	VWOS.WORK_VFRA_TYPE_CODE IN ('L','O')
GROUP BY 
	VWOS.BGN_DATE
	, VWOS.WORK_VFRA_TYPE_CODE
	, VWO.WORK_ORD_KEY;

