-- [SELECT] Step: read_mplt_LKPTRANS
-- Connection: source_db
SELECT 
	SOR_HSM_EST.EST_KEY AS EST_KEY, 
	case when max(MGT_TYPE_CODE) <= 0 and min(MGT_TYPE_CODE) = -1 then 'PSA'
	when min(MGT_TYPE_CODE) >= 0 and max(MGT_TYPE_CODE) = 1  then 'HA'
	when max(MGT_TYPE_CODE) = 0  and min(MGT_TYPE_CODE) = 0   then 'N/A'
	else 'MIXED' end AS MGT_MODE_CODE
FROM
	SOR_HSM_EST, 
	(SELECT DISTINCT SOR_HSM_BLK.EST_KEY, SOR_EMS_HSM_PRH_BLK_STS.BLK_KEY AS BLK_KEY, 
	DECODE(SOR_EMS_HSM_PRH_BLK_STS.MGT_TYPE_CODE, NULL, 0, 'HD', 1, -1) AS MGT_TYPE_CODE
	FROM
		SOR_HSM_BLK,
		SOR_EMS_HSM_PRH_BLK_STS
	WHERE
		ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1)-1 BETWEEN SOR_EMS_HSM_PRH_BLK_STS.BGN_DATE AND SOR_EMS_HSM_PRH_BLK_STS.END_DATE		
		AND SOR_HSM_BLK.BLK_KEY=SOR_EMS_HSM_PRH_BLK_STS.BLK_KEY) MGT_TYPE
WHERE
	SOR_HSM_EST.EST_KEY=MGT_TYPE.EST_KEY
GROUP BY
	SOR_HSM_EST.EST_KEY;

