-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_HSM_UNIT
select  
	TO_NUMBER(SUBSTR('$$v_rpt_mth', 5, 2))*100 + TO_NUMBER(SUBSTR('$$v_rpt_mth', 1, 4))*10000 + 200000000 AS TIME_DMNS_KEY
	, EST_KEY as EST_KEY
	, DSTR_BRD_EMMS_DSTR_KEY as DSTR_BRD_EMMS_DSTR_KEY
	, DSTR_CHC_EMMS_DSTR_KEY  as DSTR_CHC_EMMS_DSTR_KEY
	, M1.UNIT_TYPE_CODE as UNIT_TYPE_CODE
    , UNIT_ADDR_CODE as UNIT_ADDR_CODE
	, NVL(RAS.MAX_UNIT_HEAD_CNT,0) as MAX_UNIT_HEAD_CNT
	, NVL(RAS.MIN_UNIT_HEAD_CNT,0) as MIN_UNIT_HEAD_CNT
    , M1.UNIT_IFA_AREA as UNIT_IFA_AREA
	, BLK_KEY2 as BLK_KEY
	, COUNT(DISTINCT UNIT_KEY) + SUM(NVL(ADTN_ROOM_CNT, 0)) AS RCVR_UNIT_CNT
	, M1.HSM_UNIT_KEY
from (
SELECT 
	TO_NUMBER(SUBSTR('$$v_rpt_mth', 5, 2))*100 + TO_NUMBER(SUBSTR('$$v_rpt_mth', 1, 4))*10000 + 200000000 AS TIME_DMNS_KEY
	, HSU.BLK_KEY
	, HSB.EST_KEY
	, DIS.EMMS_DSTR_KEY AS DSTR_BRD_EMMS_DSTR_KEY
	, DCH.EMMS_DSTR_KEY AS DSTR_CHC_EMMS_DSTR_KEY 
	, HSU.UNIT_TYPE_CODE
    , HSU.UNIT_ADDR_CODE
	, TAMS.UNIT_KEY
	,T9.ADTN_ROOM_CNT
	,HSU.BLK_KEY  AS BLK_KEY1
	,HSU.UNIT_IFA_AREA AS UNIT_IFA_AREA
	,HSU.UNIT_TYPE_CODE AS UNIT_TYPE_CODE1
	,HSB.EMMS_BLK_KEY
	,HSB.BLK_KEY AS BLK_KEY2
	,HSU.UNIT_KEY AS HSM_UNIT_KEY
FROM 
	(SELECT TNCY_AGRMT_KEY, HSE_SRVC_APLY_KEY FROM SOR_EMS_TAM_TNCY_AGRMT) TAM
	, (SELECT TNCY_AGRMT_KEY, UNIT_KEY, TNCY_AGRMT_TM_TRMT_DATE FROM SOR_EMS_TAM_TNCY_AGRMT_STS WHERE TNCY_AGRMT_TM_STS_CODE <> 'C' 
	--AND TO_CHAR(TNCY_AGRMT_TM_TRMT_DATE, 'YYYYMM') = '$$v_rpt_mth'  
	AND (TNCY_AGRMT_TM_TRMT_DATE)>=LAST_DAY(TO_DATE('$$v_rpt_mth','YYYYMM')-1)
	AND (TNCY_AGRMT_TM_TRMT_DATE)< LAST_DAY(TO_DATE('$$v_rpt_mth','YYYYMM')) 	
	AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN BGN_DATE AND END_DATE) TAMS	
	, (SELECT u.UNIT_KEY, BLK_KEY, UNIT_IFA_AREA, us.hse_unit_type_code UNIT_TYPE_CODE, UNIT_ADDR_CODE FROM SOR_HSM_UNIT u, sor_hsm_unit_sts us WHERE substr(UNIT_ADDR_CODE,1,2)  <> 'E9' and u.unit_key = us.unit_key and add_months(to_date('$$v_rpt_mth'||'01', 'yyyymmdd'),1) - 1 between us.bgn_date and us.end_date) HSU
	, (SELECT BLK_KEY, EST_KEY, EMMS_BLK_KEY FROM SOR_HSM_BLK) HSB	
	, (
		SELECT 
			TNCY_AGRMT_KEY
			, COUNT(DISTINCT UNIT_KEY) AS ADTN_ROOM_CNT
		FROM 
			(SELECT ADTN_ROOM_KEY, UNIT_KEY, TNCY_AGRMT_KEY FROM SOR_EMS_TAM_ADTN_ROOM) ADTN
			, (SELECT ADTN_ROOM_KEY FROM SOR_EMS_TAM_ADTN_ROOM_STS WHERE ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1) - 1 BETWEEN BGN_DATE AND END_DATE) ADTS
		WHERE
			ADTN.ADTN_ROOM_KEY = ADTS.ADTN_ROOM_KEY
		GROUP BY TNCY_AGRMT_KEY
	) T9
	, (SELECT D.EMMS_DSTR_KEY, EDR.EST_KEY FROM SOR_HSM_DSTR D, SOR_HSM_EST_DSTR_RLTN EDR WHERE EDR.DSTR_KEY = D.DSTR_KEY AND DSTR_TYPE_CODE = 'DCH' AND ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1) - 1 BETWEEN BGN_DATE AND END_DATE) DCH	
	, (SELECT D.EMMS_DSTR_KEY, EDR.EST_KEY FROM SOR_HSM_DSTR D, SOR_HSM_EST_DSTR_RLTN EDR WHERE EDR.DSTR_KEY = D.DSTR_KEY AND DSTR_TYPE_CODE = 'DIS' AND ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1) - 1 BETWEEN BGN_DATE AND END_DATE) DIS	
WHERE
	TAM.TNCY_AGRMT_KEY = TAMS.TNCY_AGRMT_KEY 
	AND TAMS.UNIT_KEY = HSU.UNIT_KEY 
	AND HSU.BLK_KEY = HSB.BLK_KEY
	AND HSB.EST_KEY = DCH.EST_KEY 
	AND HSB.EST_KEY = DIS.EST_KEY
	AND NOT EXISTS (
		SELECT 
			NULL
		FROM 
			(SELECT TNCY_AGRMT_KEY, UNIT_KEY, TNCY_AGRMT_CMNC_DATE FROM SOR_EMS_TAM_TNCY_AGRMT_STS WHERE TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN BGN_DATE AND END_DATE) T9
		WHERE   
			T9.UNIT_KEY = TAMS.UNIT_KEY
			AND T9.TNCY_AGRMT_CMNC_DATE = TAMS.TNCY_AGRMT_TM_TRMT_DATE + 1)
	AND TAM.TNCY_AGRMT_KEY = T9.TNCY_AGRMT_KEY(+)
)M1
LEFT OUTER join
(
	SELECT SOR_EMS_RFX_ALCT_STD.ALCT_STD_KEY, MIN_UNIT_HEAD_CNT, MAX_UNIT_HEAD_CNT,BLK_KEY,UNIT_IFA_AREA,UNIT_TYPE_CODE FROM 
	SOR_EMS_RFX_ALCT_STD,
	SOR_EMS_RFX_ALCT_STD_STS WHERE ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1) - 1 BETWEEN BGN_DATE AND END_DATE AND SOR_EMS_RFX_ALCT_STD.ALCT_STD_KEY=SOR_EMS_RFX_ALCT_STD_STS.ALCT_STD_KEY AND SOR_EMS_RFX_ALCT_STD.UNIT_ALCT_STD_TYPE_CODE = 'O'
) RAS
on
( 
M1.BLK_KEY1 = RAS.BLK_KEY 
AND M1.UNIT_IFA_AREA = RAS.UNIT_IFA_AREA 
AND M1.UNIT_TYPE_CODE1 = RAS.UNIT_TYPE_CODE)
GROUP BY 
	TO_NUMBER(SUBSTR('$$v_rpt_mth', 5, 2))*100 + TO_NUMBER(SUBSTR('$$v_rpt_mth', 1, 4))*10000 + 200000000 
	, EST_KEY
	,DSTR_BRD_EMMS_DSTR_KEY
	, DSTR_CHC_EMMS_DSTR_KEY
	, M1.UNIT_TYPE_CODE
    , M1.UNIT_ADDR_CODE
	, RAS.MIN_UNIT_HEAD_CNT
	, RAS.MAX_UNIT_HEAD_CNT
    , M1.UNIT_IFA_AREA
	, BLK_KEY2
	, M1.HSM_UNIT_KEY;

-- [SELECT] Step: read_mplt_LKPTRANS
-- Connection: source_db
SELECT 
	SOR_HSM_EST.EST_KEY AS EST_KEY, 
	case when max(MGT_TYPE_CODE) <= 0 and min(MGT_TYPE_CODE) = -1 then 'PSA'
	when min(MGT_TYPE_CODE) >= 0 and max(MGT_TYPE_CODE) = 1  then 'HA'
	when max(MGT_TYPE_CODE) = 0  and min(MGT_TYPE_CODE) = 0   then 'N/A'
	else 'MIXED' end AS MGT_MODE_CODE
FROM
	SOR_HSM_EST, 
	(SELECT DISTINCT SOR_HSM_BLK.EST_KEY, SOR_EMS_HSM_PRH_BLK_STS.BLK_KEY AS BLK_KEY, 
	DECODE(SOR_EMS_HSM_PRH_BLK_STS.MGT_TYPE_CODE, NULL, 0, 'HD', 1, -1) AS MGT_TYPE_CODE
	FROM
		SOR_HSM_BLK,
		SOR_EMS_HSM_PRH_BLK_STS
	WHERE
		ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1)-1 BETWEEN SOR_EMS_HSM_PRH_BLK_STS.BGN_DATE AND SOR_EMS_HSM_PRH_BLK_STS.END_DATE		
		AND SOR_HSM_BLK.BLK_KEY=SOR_EMS_HSM_PRH_BLK_STS.BLK_KEY) MGT_TYPE
WHERE
	SOR_HSM_EST.EST_KEY=MGT_TYPE.EST_KEY
GROUP BY
	SOR_HSM_EST.EST_KEY;

