and add_months(to_date('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1 between ES.BGN_DATE and ES.END_DATE
and add_months(to_date('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1 between US.BGN_DATE and US.END_DATE
group by UNIT_ADDR_CODE;

