-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_EMS_PHA_APLY_OFR
SELECT 	OFU.UNIT_KEY,
					OFR.OFR_DATE,
					OFRS.PRVS_ACPT_DATE,
	 				OFRS.OFR_STS_CODE,
	 				OFR.CUST_KEY,
	 				OFR.HSE_SRVC_APLY_KEY,
	 				OFR.OFR_KEY
	         FROM    SOR_EMS_PHA_APLY_OFR            OFR,
	                 SOR_EMS_PHA_APLY_OFR_STS        OFRS,
	                 SOR_EMS_PHA_APLY_OFR_UNIT_RLTN  OFU
, (select ts.unit_key, max(ts.tncy_agrmt_tm_trmt_date) as tncy_agrmt_trmt_date
from sor_ems_tam_tncy_agrmt_sts ts
where to_date('$$v_snsh_date', 'yyyymmdd') between ts.bgn_date and ts.end_date
group by ts.unit_key 
having max(ts.tncy_agrmt_tm_trmt_date) is not null and to_char(max(ts.tncy_agrmt_trmt_date),'yyyymm') <> '$$v_rpt_mth') txa,
(select ts.unit_key, min(ts.tncy_agrmt_tm_trmt_date) as tncy_agrmt_trmt_date
from sor_ems_tam_tncy_agrmt_sts ts
where to_date('$$v_snsh_date', 'yyyymmdd') between ts.bgn_date and ts.end_date
and to_char(tncy_agrmt_trmt_date,'yyyymm') = '$$v_rpt_mth' and ts.tncy_agrmt_tm_trmt_date is not null
group by ts.unit_key) txb
	         WHERE   OFR.OFR_KEY = OFRS.OFR_KEY
	         AND     OFR.OFR_KEY = OFU.OFR_KEY
	         AND     TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN OFRS.BGN_DATE AND OFRS.END_DATE 
and ofu.unit_key=txa.unit_key (+)
and ofu.unit_key=txb.unit_key (+)
and (txa.unit_key is not null or txb.unit_key is not null)
and ((ofr.ofr_date >= txa.tncy_agrmt_trmt_date)
  or (ofr.ofr_date >= txb.tncy_agrmt_trmt_date))
ORDER BY OFU.UNIT_KEY;

-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_EMS_TAM_TNCY_AGRMT
SELECT 
	UNIT_KEY,
				TNCY_AGRMT_CMNC_DATE,
				TNCY_AGRMT_TM_TRMT_DATE,
				TNCY_AGRMT_TM_STS_CODE,
				CUST_KEY,
				HSE_SRVC_APLY_KEY,
				TNCY_AGRMT_KEY
FROM (
SELECT         
				TAMS.UNIT_KEY,
				TAMS.TNCY_AGRMT_CMNC_DATE,
				TAMS.TNCY_AGRMT_TM_TRMT_DATE,
				TAMS.TNCY_AGRMT_TM_STS_CODE,
				TAM.CUST_KEY,
				TAM.HSE_SRVC_APLY_KEY,
				TAM.TNCY_AGRMT_KEY
        FROM    SOR_EMS_TAM_TNCY_AGRMT              TAM,
                SOR_EMS_TAM_TNCY_AGRMT_STS          TAMS
                --SOR_HSM_UNIT                        HSU,
                --SOR_HSM_UNIT_STS                    HSUS
        WHERE   TAM.TNCY_AGRMT_KEY = TAMS.TNCY_AGRMT_KEY
        AND TAMS.TNCY_AGRMT_TM_STS_CODE IN ('A','I','P')
        AND    TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN TAMS.BGN_DATE  AND TAMS.END_DATE
UNION ALL
-- Include additional rooms
SELECT         
				RM.UNIT_KEY,
				TAMS.TNCY_AGRMT_CMNC_DATE,
				TAMS.TNCY_AGRMT_TM_TRMT_DATE,
				TAMS.TNCY_AGRMT_TM_STS_CODE,
				TAM.CUST_KEY,
				TAM.HSE_SRVC_APLY_KEY,
				TAM.TNCY_AGRMT_KEY
        FROM    SOR_EMS_TAM_TNCY_AGRMT              TAM,
                SOR_EMS_TAM_TNCY_AGRMT_STS          TAMS,
			SOR_EMS_TAM_ADTN_ROOM 				RM
                --SOR_HSM_UNIT                        HSU,
                --SOR_HSM_UNIT_STS                    HSUS
        WHERE   TAM.TNCY_AGRMT_KEY = TAMS.TNCY_AGRMT_KEY
	AND RM.TNCY_AGRMT_KEY = TAM.TNCY_AGRMT_KEY
        AND TAMS.TNCY_AGRMT_TM_STS_CODE IN ('A','I','P')
        AND    TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN TAMS.BGN_DATE  AND TAMS.END_DATE
)ORDER BY UNIT_KEY;

-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_HSM_UNIT
select
HSU.UNIT_KEY,
HSU.UNIT_ADDR_CODE,
est.est_key AS EST_KEY,
dch.EMMS_DSTR_KEY as EMMS_DTSR_CHC_DSTR_KEY,
dis.EMMS_DSTR_KEY as EMMS_DTSR_BRD_DSTR_KEY,
RFX.UNIT_TYPE_CODE,
RFX.UNIT_IFA_AREA,
RFXS.MAX_UNIT_HEAD_CNT,
RFXS.MIN_UNIT_HEAD_CNT
 from 
SOR_HSM_UNIT 	HSU,
--SOR_HSM_UNIT_STS 	HSUS,
SOR_EMS_RFX_ALCT_STD 	RFX,
SOR_EMS_RFX_ALCT_STD_STS RFXS,
sor_hsm_blk blk,
sor_hsm_est est,
sor_ems_hsm_prh_est_sts PRH,
(SELECT D.EMMS_DSTR_KEY, EDR.EST_KEY FROM SOR_HSM_DSTR D, SOR_HSM_EST_DSTR_RLTN EDR WHERE EDR.DSTR_KEY = D.DSTR_KEY AND DSTR_TYPE_CODE = 'DCH' AND LAST_DAY(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD')) BETWEEN BGN_DATE AND END_DATE) DCH,
(SELECT D.EMMS_DSTR_KEY, EDR.EST_KEY FROM SOR_HSM_DSTR D, SOR_HSM_EST_DSTR_RLTN EDR WHERE EDR.DSTR_KEY = D.DSTR_KEY AND DSTR_TYPE_CODE = 'DIS' AND LAST_DAY(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD')) BETWEEN BGN_DATE AND END_DATE) DIS
where 
--HSU.UNIT_KEY = HSUS.UNIT_KEY
--AND LAST_DAY(TO_DATE('$$v_rpt_mth' || '01','yyyymmdd')) between HSUS.bgn_date and HSUS.end_date
RFX.ALCT_STD_KEY =  RFXS.ALCT_STD_KEY
AND LAST_DAY(TO_DATE('$$v_rpt_mth' || '01','yyyymmdd')) between RFXS.bgn_date and RFXS.end_date
AND HSU.BLK_KEY = RFX.BLK_KEY 
AND HSU.UNIT_IFA_AREA= RFX.UNIT_IFA_AREA
AND HSU.UNIT_TYPE_CODE = RFX.UNIT_TYPE_CODE
and HSU.UNIT_ADDR_CODE not like 'E9%'
AND HSU.blk_key = blk.blk_key and 
blk.est_key = est.est_key and 
est.est_key = dch.est_key and
est.est_key = dis.est_key and 
PRH.EST_KEY = EST.EST_KEY and 
LAST_DAY(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD')) BETWEEN prh.BGN_DATE AND prh.END_DATE and 
RFX.UNIT_ALCT_STD_TYPE_CODE = 'O'
order by HSU.unit_key;

