-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_HSM_UNIT
select 
	M1.UNIT_ADDR_CODE, 
	M1.UNIT_KEY,
	M1.EMMS_UNIT_KEY,
	M1.UNIT_TAKE_OVER_DATE,
	NVL(A1.MAX_UNIT_HEAD_CNT,0) AS MAX_UNIT_HEAD_CNT,
	NVL(A1.MIN_UNIT_HEAD_CNT,0) AS MIN_UNIT_HEAD_CNT,
	M1.UNIT_IFA_AREA,
	M1.UNIT_TYPE_CODE,
	M1.HSE_UNIT_TM_STS_CODE,
	M1.HSE_UNIT_TM_VOID_STS_BGN_DATE,
	M1.HSE_UNIT_DMLH_DATE,
	M1.UNIT_RSRV_CATG_CODE,
	M1.HSE_UNIT_RSRV_OPR_CODE,
	M1.UNIT_ALCT_STS_CODE,
	M1.HSE_UNIT_ENV_CODE 
from
(
	select 
	HSU.UNIT_ADDR_CODE, 
	HSU.UNIT_KEY,
	HSU.EMMS_UNIT_KEY,
	HPUS.UNIT_TAKE_OVER_DATE,
	HSB.BLK_KEY,
	HSU.UNIT_IFA_AREA,
	HSU.UNIT_TYPE_CODE,
	HSUS.HSE_UNIT_TM_STS_CODE,
	HSUS.HSE_UNIT_TM_VOID_STS_BGN_DATE,
	HSUS.HSE_UNIT_DMLH_DATE,
	HSUS.UNIT_RSRV_CATG_CODE,
	HSUS.HSE_UNIT_RSRV_OPR_CODE,
	HPUS.UNIT_ALCT_STS_CODE,
	HSUS.HSE_UNIT_ENV_CODE
	FROM    
		SOR_HSM_UNIT                HSU,
			SOR_HSM_UNIT_STS            HSUS,
			SOR_HSM_BLK                 HSB,
			SOR_EMS_HSM_BLK             EMB,
			SOR_EMS_HSM_BLK_STS         EMBS,
		SOR_EMS_HSM_PRH_UNIT_STS    HPUS
	WHERE   
		HSU.UNIT_KEY = HSUS.UNIT_KEY
	and 	HSU.UNIT_KEY = HPUS.UNIT_KEY
	AND     HSU.BLK_KEY = HSB.BLK_KEY
	AND     HSB.EMMS_BLK_KEY = EMB.BLK_BK
	AND     EMB.BLK_KEY = EMBS.BLK_KEY
	AND     (EMBS.HSE_BLK_END_DATE IS NULL
	OR       EMBS.HSE_BLK_END_DATE > ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1) - 1)
	AND     EMBS.BLK_CMPLT_DATE <= ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1) - 1
	AND     EMBS.BLK_HOVR_DATE <= ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1) - 1
	and 	add_months(to_date('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1 between HPUS.BGN_DATE and HPUS.END_DATE
	AND     ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1) - 1 BETWEEN HSUS.BGN_DATE AND HSUS.END_DATE
	AND     ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1) - 1 BETWEEN EMBS.BGN_DATE AND EMBS.END_DATE
	AND     HSUS.HSE_UNIT_TM_STS_CODE IN ('VCNT', 'OCPY', 'TOBETERM')
	AND     (HSUS.HSE_UNIT_DMLH_DATE IS NULL
	OR       HSUS.HSE_UNIT_DMLH_DATE > ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1) - 1)
--	AND     HPUS.UNIT_TAKE_OVER_DATE <= ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1) - 1
	AND     HSU.UNIT_ADDR_CODE NOT LIKE 'E9%'
)M1
LEFT OUTER JOIN
(	SELECT
	MAX_UNIT_HEAD_CNT,
	MIN_UNIT_HEAD_CNT,
	BLK_KEY,
	UNIT_TYPE_CODE,
	UNIT_IFA_AREA
	FROM
	SOR_EMS_RFX_ALCT_STD        AST,
	SOR_EMS_RFX_ALCT_STD_STS    ASTS
	WHERE
    AST.ALCT_STD_KEY = ASTS.ALCT_STD_KEY
	AND UNIT_ALCT_STD_TYPE_CODE = 'O'
	AND ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1) - 1 BETWEEN ASTS.BGN_DATE AND ASTS.END_DATE
)A1
ON	
(	 	
	        M1.BLK_KEY = A1.BLK_KEY
	AND     M1.UNIT_TYPE_CODE = A1.UNIT_TYPE_CODE
	AND     M1.UNIT_IFA_AREA = A1.UNIT_IFA_AREA
);

-- [SELECT] Step: read_LKP_SOR_EMS_SRP_MRRS_RENT_RCV
