select SOR_EMS_SRP_MRRS_RENT_RCV.UNIT_KEY as UNIT_KEY,
nvl(SOR_EMS_SRP_MRRS_RENT_RCV.UNIT_GRS_RENT_AMT,0) as UNIT_GRS_RENT_AMT
from SOR_EMS_SRP_MRRS_RENT_RCV
where (SOR_EMS_SRP_MRRS_RENT_RCV.SYS_RPT_YEAR*100+SOR_EMS_SRP_MRRS_RENT_RCV.SYS_RPT_MTH) = to_number('$$v_rpt_mth');

-- [SELECT] Step: read_LKP_UNIT_ADVS_ENV_CODE_IND
-- Connection: DPA
select unit_key as UNIT_KEY, max(e1) as EI2, max(e2) as EI3, max(e3) as EI4 from
(
select t1.unit_key, e1, e2, e3 from
	 (select unit_key, max(unit_scnd_env_code) e1 from SOR_EMS_HSM_UNIT_SCND_ENV group by unit_key) t1
	 left outer join
	 (select unit_key, unit_scnd_env_code e2 from SOR_EMS_HSM_UNIT_SCND_ENV) t2
	 on
	 t1.unit_key = t2.unit_key and e2 < e1
	 left outer join 
	 (select unit_key, unit_scnd_env_code e3 from SOR_EMS_HSM_UNIT_SCND_ENV) t3
	 on 
	 t2.unit_key = t3.unit_key and e3 < e2
	 ) f_final group by unit_key;

-- [SELECT] Step: read_LKP_LAST_TPS_DOT
-- Connection: DPA
SELECT (T.TPS_AGRMT_TRMT_DATE + 1) as LAST_TPS_DOT, UNIT_KEY as UNIT_KEY
FROM SOR_EMS_TOW_TPS_AGRMT_STS T
WHERE T.TPS_AGRMT_EXOWNR_REF_CODE IS NOT NULL
AND T.TPS_TRMT_TYPE_CODE IN ( 'B', 'RS', 'RN' )
and to_date('$$v_snsh_date', 'YYYYMMDD') between bgn_date and end_date;

-- [SELECT] Step: read_LKP_LAST_DOT
-- Connection: DPA
SELECT MAX( TNCY_AGRMT_TM_TRMT_DATE + 1 ) as LAST_DOT, UNIT_KEY as UNIT_KEY
FROM (
SELECT M.TNCY_AGRMT_TM_TRMT_DATE, M.UNIT_KEY
FROM SOR_EMS_TAM_TNCY_AGRMT_STS M
where to_date('$$v_snsh_date', 'YYYYMMDD') between M.bgn_date and M.end_date
and M.TNCY_AGRMT_TM_TRMT_DATE is not null
UNION
SELECT TAS.TNCY_AGRMT_TM_TRMT_DATE, AR.UNIT_KEY
FROM SOR_EMS_TAM_ADTN_ROOM AR, SOR_EMS_TAM_TNCY_AGRMT_STS TAS
WHERE AR.TNCY_AGRMT_KEY = TAS.TNCY_AGRMT_KEY
and TAS.TNCY_AGRMT_TM_TRMT_DATE is not null)
group by UNIT_KEY;

