DECODE(DT_TK_OVER,NULL,'ADV',
DECODE(FL_ALLO_ST, '0', 'PA', '1',
DECODE(OFFER_STAT,NULL,DECODE(RES_CAT,'GWLEFASM','AMA','AOA'),'AOA'), 'AOA'
)) as ALCT_STS_CODE, 
RPAD(EST_TYPE, 1, ' ')||RPAD(trim(ESTATE), 4, ' ')||LPAD(trim(BLK), 3, ' ')||RPAD(ROOM, 7, ' ') as UNIT_ADDR_CODE
