(select D.EMMS_DSTR_KEY, EDR.EST_KEY from SOR_HSM_DSTR D, SOR_HSM_EST_DSTR_RLTN EDR
WHERE EDR.DSTR_KEY = D.DSTR_KEY  AND DSTR_TYPE_CODE = 'DCH' 
AND add_months(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),-1)-1 BETWEEN BGN_DATE AND END_DATE) DCH,
(select D.EMMS_DSTR_KEY, EDR.EST_KEY from SOR_HSM_DSTR D, SOR_HSM_EST_DSTR_RLTN EDR
WHERE EDR.DSTR_KEY = D.DSTR_KEY  AND DSTR_TYPE_CODE = 'DIS'
AND add_months(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),-1)-1 BETWEEN BGN_DATE AND END_DATE) DIS,
SOR_HSM_UNIT U, 
SOR_HSM_BLK B, 
