-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_EMS_HSM_UNIT_STS1
select 
t1.unit_key,
t1.UNIT_RSRV_CATG_CODE,
nvl(max(t2.bd2),t1.bd1) as BGN_DATE,
t1.ed1 AS END_DATE
from (
select 
U1.unit_key AS UNIT_KEY, 
U1.UNIT_RSRV_CATG_CODE AS UNIT_RSRV_CATG_CODE,
U1.bgn_date as bd1,
U1.end_date as ed1,
U2.bgn_date as bd2,
U2.end_date as ed2 
from sor_hsm_unit_sts U1
LEFT OUTER JOIN 
sor_hsm_unit_sts U2
ON
U1.UNIT_KEY = U2.UNIT_KEY AND 
U1.END_DATE  = U2.BGN_DATE -1
WHERE
U1.UNIT_RSRV_CATG_CODE is not null 
AND  (U1.UNIT_RSRV_CATG_CODE <> U2.UNIT_RSRV_CATG_CODE OR U2.UNIT_RSRV_CATG_CODE IS NULL) 
) t1 left outer join 
(select 
U1.unit_key AS UNIT_KEY, 
U1.UNIT_RSRV_CATG_CODE AS UNIT_RSRV_CATG_CODE,
U1.bgn_date as bd1,
U1.end_date as ed1,
U2.bgn_date as bd2,
U2.end_date as ed2
from sor_hsm_unit_sts U1
LEFT OUTER JOIN 
sor_hsm_unit_sts U2
ON
U1.UNIT_KEY = U2.UNIT_KEY AND 
U1.END_DATE  = U2.BGN_DATE -1
WHERE
U1.UNIT_RSRV_CATG_CODE is not null 
AND  (U1.UNIT_RSRV_CATG_CODE <> U2.UNIT_RSRV_CATG_CODE OR U2.UNIT_RSRV_CATG_CODE IS NULL) 
) t2
on t1.unit_key = t2.unit_key and t1.UNIT_RSRV_CATG_CODE <> t2.UNIT_RSRV_CATG_CODE
and t1.bd1>t2.bd1
group by  
t1.unit_key,t1.UNIT_RSRV_CATG_CODE,
t1.bd1,
t1.ed1
order by unit_key,UNIT_RSRV_CATG_CODE;

-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_HSM_UNIT
select 
HSU.UNIT_KEY,
HSU.UNIT_ADDR_CODE,
est.est_key AS EST_KEY,
dch.EMMS_DSTR_KEY as EMMS_DTSR_CHC_DSTR_KEY,
dis.EMMS_DSTR_KEY as EMMS_DTSR_BRD_DSTR_KEY,
RFX.UNIT_TYPE_CODE,
RFX.UNIT_IFA_AREA,
RFXS.MAX_UNIT_HEAD_CNT,
RFXS.MIN_UNIT_HEAD_CNT,
HSUS.HSE_UNIT_ENV_CODE  as HSE_UNIT_ENV_CODE 
 from 
SOR_HSM_UNIT 	HSU,
SOR_HSM_UNIT_STS 	HSUS,
SOR_EMS_RFX_ALCT_STD 	RFX,
SOR_EMS_RFX_ALCT_STD_STS RFXS,
sor_hsm_blk blk,
sor_hsm_est est,
sor_ems_hsm_prh_est_sts PRH,
(SELECT D.EMMS_DSTR_KEY, EDR.EST_KEY FROM SOR_HSM_DSTR D, SOR_HSM_EST_DSTR_RLTN EDR WHERE EDR.DSTR_KEY = D.DSTR_KEY AND DSTR_TYPE_CODE = 'DCH' AND TO_DATE('$$v_snsh_date','yyyymmdd') BETWEEN BGN_DATE AND END_DATE) DCH,
(SELECT D.EMMS_DSTR_KEY, EDR.EST_KEY FROM SOR_HSM_DSTR D, SOR_HSM_EST_DSTR_RLTN EDR WHERE EDR.DSTR_KEY = D.DSTR_KEY AND DSTR_TYPE_CODE = 'DIS' AND TO_DATE('$$v_snsh_date','yyyymmdd') BETWEEN BGN_DATE AND END_DATE) DIS
where 
HSU.UNIT_KEY = HSUS.UNIT_KEY
AND TO_DATE('$$v_snsh_date','yyyymmdd') between HSUS.bgn_date and HSUS.end_date
AND RFX.ALCT_STD_KEY =  RFXS.ALCT_STD_KEY
AND TO_DATE('$$v_snsh_date','yyyymmdd') between RFXS.bgn_date and RFXS.end_date
AND HSU.BLK_KEY = RFX.BLK_KEY 
AND HSU.UNIT_IFA_AREA= RFX.UNIT_IFA_AREA
AND HSU.UNIT_TYPE_CODE = RFX.UNIT_TYPE_CODE
AND HSU.blk_key = blk.blk_key and 
blk.est_key = est.est_key and 
est.est_key = dch.est_key and
est.est_key = dis.est_key and 
PRH.EST_KEY = EST.EST_KEY and 
TO_DATE('$$v_snsh_date','yyyymmdd') BETWEEN prh.BGN_DATE AND prh.END_DATE and 
RFX.UNIT_ALCT_STD_TYPE_CODE = 'O'
ORDER BY HSU.UNIT_KEY;

-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_EMS_PHA_APLY_OFR_RFSL
SELECT          HSU.UNIT_KEY AS UNIT_KEY,
			RFS.OFR_RFSL_KEY AS OFR_RFSL_KEY,
			RFSS.OFR_RFSL_DATE AS OFR_RFSL_DATE
        FROM    SOR_EMS_PHA_APLY_OFR            OFR,
                SOR_EMS_PHA_APLY_OFR_STS        OFRS,
                SOR_EMS_PHA_APLY_OFR_UNIT_RLTN  OFU,
                SOR_HSM_UNIT                    HSU,
                SOR_HSM_UNIT_STS                HSUS,
                SOR_EMS_PHA_APLY_OFR_RFSL       RFS,
                SOR_EMS_PHA_APLY_OFR_RFSL_STS   RFSS
        WHERE   OFR.OFR_KEY = OFRS.OFR_KEY
        AND     OFR.OFR_KEY = OFU.OFR_KEY
        AND     TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN OFRS.BGN_DATE AND OFRS.END_DATE
        AND     OFU.UNIT_KEY = HSU.UNIT_KEY
        AND     HSU.UNIT_KEY = HSUS.UNIT_KEY
        AND     TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN HSUS.BGN_DATE AND HSUS.END_DATE
        AND     RFS.OFR_KEY = OFR.OFR_KEY
        AND     RFS.OFR_RFSL_KEY = RFSS.OFR_RFSL_KEY
        AND     TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN RFSS.BGN_DATE AND RFSS.END_DATE
order by  HSU.UNIT_KEY;

-- [SELECT] Step: read_LKPTRANS
-- Connection: DPA
SELECT 
				UNIT_KEY as UNIT_KEY,
				TNCY_AGRMT_CMNC_DATE AS TNCY_AGRMT_CMNC_DATE,
				TNCY_AGRMT_TM_TRMT_DATE AS TNCY_AGRMT_TM_TRMT_DATE,
				TNCY_AGRMT_TM_STS_CODE AS TNCY_AGRMT_TM_STS_CODE,
				CUST_KEY AS CUST_KEY,
				HSE_SRVC_APLY_KEY AS HSE_SRVC_APLY_KEY,
				TNCY_AGRMT_KEY AS TNCY_AGRMT_KEY
FROM (SELECT         
				TAMS.UNIT_KEY as UNIT_KEY,
				TAMS.TNCY_AGRMT_CMNC_DATE AS TNCY_AGRMT_CMNC_DATE,
				TAMS.TNCY_AGRMT_TM_TRMT_DATE AS TNCY_AGRMT_TM_TRMT_DATE,
				TAMS.TNCY_AGRMT_TM_STS_CODE AS TNCY_AGRMT_TM_STS_CODE,
				TAM.CUST_KEY AS CUST_KEY,
				TAM.HSE_SRVC_APLY_KEY AS HSE_SRVC_APLY_KEY,
				TAM.TNCY_AGRMT_KEY AS TNCY_AGRMT_KEY
        FROM    SOR_EMS_TAM_TNCY_AGRMT              TAM,
                SOR_EMS_TAM_TNCY_AGRMT_STS          TAMS
                --SOR_HSM_UNIT                        HSU,
                --SOR_HSM_UNIT_STS                    HSUS
        WHERE   TAM.TNCY_AGRMT_KEY = TAMS.TNCY_AGRMT_KEY
        AND TAMS.TNCY_AGRMT_TM_STS_CODE IN ('A','I')
        AND     TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN TAMS.BGN_DATE  AND TAMS.END_DATE
union all
SELECT     	RM.UNIT_KEY as UNIT_KEY,
				TAMS.TNCY_AGRMT_CMNC_DATE AS TNCY_AGRMT_CMNC_DATE,
				TAMS.TNCY_AGRMT_TM_TRMT_DATE AS TNCY_AGRMT_TM_TRMT_DATE,
				TAMS.TNCY_AGRMT_TM_STS_CODE AS TNCY_AGRMT_TM_STS_CODE,
				TAM.CUST_KEY AS CUST_KEY,
				TAM.HSE_SRVC_APLY_KEY AS HSE_SRVC_APLY_KEY,
				TAM.TNCY_AGRMT_KEY AS TNCY_AGRMT_KEY
        FROM    SOR_EMS_TAM_TNCY_AGRMT              TAM,
                SOR_EMS_TAM_TNCY_AGRMT_STS          TAMS,
                SOR_EMS_TAM_ADTN_ROOM		    RM
        WHERE   TAM.TNCY_AGRMT_KEY = TAMS.TNCY_AGRMT_KEY
	AND RM.TNCY_AGRMT_KEY = TAMS.TNCY_AGRMT_KEY
        AND TAMS.TNCY_AGRMT_TM_STS_CODE IN ('A','I')
        AND     TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN TAMS.BGN_DATE  AND TAMS.END_DATE
);

-- [SELECT] Step: read_LKP_UNIT_ADVS_ENV_CODE_IND
-- Connection: DPA
select unit_key as UNIT_KEY, max(e1) as EI2, max(e2) as EI3, max(e3) as EI4 from
(
select t1.unit_key, e1, e2, e3 from
	 (select unit_key, max(unit_scnd_env_code) e1 from SOR_EMS_HSM_UNIT_SCND_ENV group by unit_key) t1
	 left outer join
	 (select unit_key, unit_scnd_env_code e2 from SOR_EMS_HSM_UNIT_SCND_ENV) t2
	 on
	 t1.unit_key = t2.unit_key and e2 < e1
	 left outer join 
	 (select unit_key, unit_scnd_env_code e3 from SOR_EMS_HSM_UNIT_SCND_ENV) t3
	 on 
	 t2.unit_key = t3.unit_key and e3 < e2
	 ) f_final group by unit_key;

