-- [SOURCE_QUALIFIER] Step: apply_SELF_WITHDRAW_CANCEL
SELECT distinct
  TAM.UNIT_KEY             -- ORIGINAL ADDRESS
  ,CASE.REF_CASE_TYPE_CODE     -- TRANSFER TYPE CODE
  ,CASE.OR_TYPE_CODE           -- TRANSFER SUB-TYPE CODE
  ,CASE.TFR_RSN_CODE           -- TRANSFER REASON
FROM 
  SOR_EMS_TRF_REF_CASE TRC
  ,SOR_EMS_TRF_REF_CASE_STS      CASE
  ,(select REF_CASE_KEY, PRH_APLY_STG_CODE, PRH_APLY_STS_UPD_DATE, PRH_APLY_STG_UPD_DATE, PRH_APLY_STS_CODE, HSE_SRVC_APLY_KEY 
FROM SOR_EMS_PHA_APLY_STS A, SOR_EMS_PHA_APLY B 
WHERE A.APLY_KEY = B.APLY_KEY AND TO_CHAR(PRH_APLY_STS_UPD_DATE, 'YYYYMM') = '$$v_rpt_mth'
      AND TO_CHAR(PRH_APLY_STG_UPD_DATE, 'YYYYMM') = '$$v_rpt_mth' 
and                                               
 (ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1) - 1 BETWEEN a.BGN_DATE AND a.END_DATE 
  OR NOT EXISTS 
    (
      SELECT 
        NULL 
      FROM 
        SOR_EMS_PHA_APLY_STS
      WHERE 
        BGN_DATE > a.BGN_DATE
        AND APLY_KEY = a.APLY_KEY
        AND TO_CHAR(PRH_APLY_STS_UPD_DATE, 'YYYYMM') = '$$v_rpt_mth'
        AND TO_CHAR(PRH_APLY_STG_UPD_DATE, 'YYYYMM') = '$$v_rpt_mth'
    )
  )
) PAS
  ,SOR_EMS_TAM_TNCY_AGRMT_STS    TAM
WHERE 
  CASE.REF_CASE_KEY = TRC.REF_CASE_KEY
  AND TRC.REF_CASE_BK = PAS.REF_CASE_KEY (+)
  AND CASE.TNCY_AGRMT_KEY = TAM.TNCY_AGRMT_KEY
  and tam.TNCY_AGRMT_TM_STS_CODE <> 'C'
  and
  (ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1) - 1 BETWEEN case.BGN_DATE AND case.END_DATE
   OR NOT EXISTS 
    (
      SELECT 
        NULL 
      FROM 
        SOR_EMS_TRF_REF_CASE_STS case_del
      WHERE 
        BGN_DATE > CASE.BGN_DATE
        AND ref_case_key = case.ref_case_key
    )
  )
  AND add_months(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1 BETWEEN TAM.BGN_DATE AND TAM.END_DATE
  AND
  (
    /* WITH APPLICATION */
    (
      PAS.HSE_SRVC_APLY_KEY IS NOT NULL
      AND PAS.PRH_APLY_STG_CODE || PAS.PRH_APLY_STS_CODE = '3C'
      AND TO_CHAR(PAS.PRH_APLY_STS_UPD_DATE, 'YYYYMM') = '$$v_rpt_mth'
      AND TO_CHAR(PAS.PRH_APLY_STG_UPD_DATE, 'YYYYMM') = '$$v_rpt_mth'
    ) OR
    /* WITHOUT APPLICATION */
    (
      PAS.HSE_SRVC_APLY_KEY IS NULL
      AND ( CASE.REF_CASE_STS_CODE IN ('CLOS', 'NFA') OR (CASE.REF_CASE_STS_CODE = 'CMPL' AND CASE.LU_STS_CODE = 'CNL') )
      AND TO_CHAR(CASE.REF_CASE_STS_UPD_DATE, 'YYYYMM') = '$$v_rpt_mth'
    )
  )
UNION
SELECT distinct
  TAM.UNIT_KEY             -- ORIGINAL ADDRESS
  ,DECODE(OPR_TYPE_CODE,       -- TRANSFER TYPE CODE
  '6','XTR',
  '7','INH',
  '9','STR',
  '10','TRW',
  '11','OCR',
  '13','OCR',
  '14','HFT',
  '15','HFT')
  ,NULL                        -- TRANSFER SUB-TYPE CODE
  ,NULL                        -- TRANSFER REASON
FROM
  SOR_EMS_PHA_APLY      APLY
  ,SOR_EMS_PHA_APLY_STS	 PAS
  ,SOR_EMS_TAM_TNCY_AGRMT_STS   TAM
  ,SOR_EMS_POR_OPR          OPR
  ,SOR_EMS_POR_OPR_STS          OPRS
  ,SOR_HSM_UNIT   UNIT
WHERE
  PAS.APLY_KEY = APLY.APLY_KEY
  AND PAS.TNCY_AGRMT_KEY = TAM.TNCY_AGRMT_KEY
  AND OPR.OPR_CODE = PAS.OPR_CODE
  AND OPR.OPR_KEY = OPRS.OPR_KEY
  AND PAS.REF_CASE_KEY IS NULL
  AND OPRS.OPR_TYPE_CODE IN ('6', '7', '9', '10', '11', '13', '14', '15')
  AND PAS.PRH_APLY_STG_CODE || PAS.PRH_APLY_STS_CODE = '3C'
  AND TO_CHAR(PAS.PRH_APLY_STS_UPD_DATE, 'YYYYMM') = '$$v_rpt_mth'
  AND TO_CHAR(PAS.PRH_APLY_STG_UPD_DATE, 'YYYYMM') = '$$v_rpt_mth'
  and tam.TNCY_AGRMT_TM_STS_CODE <> 'C'
 and                                               
 (ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1) - 1 BETWEEN PAS.BGN_DATE AND PAS.END_DATE 
  OR NOT EXISTS 
    (
      SELECT 
        NULL 
      FROM 
        SOR_EMS_PHA_APLY_STS
      WHERE 
        BGN_DATE > PAS.BGN_DATE
        AND APLY_KEY = PAS.APLY_KEY
    )
)
  AND add_months(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1 BETWEEN OPRS.BGN_DATE AND OPRS.END_DATE
  AND add_months(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1 BETWEEN TAM.BGN_DATE AND TAM.END_DATE;

-- [SOURCE_QUALIFIER] Step: apply_HOUSED_CASE
SELECT distinct
TAM.UNIT_KEY             -- ORIGINAL ADDRESS
  ,CASE.REF_CASE_TYPE_CODE     -- TRANSFER TYPE CODE
  ,CASE.OR_TYPE_CODE           -- TRANSFER SUB-TYPE CODE
  ,CASE.TFR_RSN_CODE           -- TRANSFER REASON
FROM 
SOR_EMS_TRF_REF_CASE TRC
  ,SOR_EMS_TRF_REF_CASE_STS   CASE
  ,SOR_EMS_PHA_APLY      APLY
  ,SOR_EMS_PHA_APLY_STS	 PAS
  ,SOR_EMS_TAM_TNCY_AGRMT_STS    TAM
  ,(SELECT HSE_SRVC_APLY_KEY, TNCY_AGRMT_CMNC_DATE, TNCY_AGRMT_TM_STS_CODE
  FROM
  SOR_EMS_TAM_TNCY_AGRMT_STS TAS
  , SOR_EMS_TAM_TNCY_AGRMT TA
  WHERE 
  TA.TNCY_AGRMT_KEY = TAS.TNCY_AGRMT_KEY
  AND TO_CHAR(TNCY_AGRMT_CMNC_DATE,'YYYYMM') = '$$v_rpt_mth'
  AND TNCY_AGRMT_TM_STS_CODE IN ('A','P')
  AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN BGN_DATE AND END_DATE
  ) TAM_NEW
WHERE 
  PAS.APLY_KEY = APLY.APLY_KEY
  AND CASE.REF_CASE_KEY = TRC.REF_CASE_KEY 
  AND TRC.REF_CASE_BK = PAS.REF_CASE_KEY 
  AND CASE.TNCY_AGRMT_KEY = TAM.TNCY_AGRMT_KEY
  AND APLY.HSE_SRVC_APLY_KEY = TAM_NEW.HSE_SRVC_APLY_KEY
 AND PAS.PRH_APLY_STG_CODE || PAS.PRH_APLY_STS_CODE = '8P'
  and tam.TNCY_AGRMT_TM_STS_CODE <> 'C'
  AND add_months(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1 BETWEEN CASE.BGN_DATE AND CASE.END_DATE
  AND add_months(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1 BETWEEN PAS.BGN_DATE AND PAS.END_DATE
  AND add_months(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1 BETWEEN TAM.BGN_DATE AND TAM.END_DATE
UNION
SELECT distinct
  TAM.UNIT_KEY             -- ORIGINAL ADDRESS
  ,CASE.REF_CASE_TYPE_CODE     -- TRANSFER TYPE CODE
  ,CASE.OR_TYPE_CODE           -- TRANSFER SUB-TYPE CODE
  ,CASE.TFR_RSN_CODE           -- TRANSFER REASON
FROM 
  SOR_EMS_TRF_REF_CASE TRC
  ,SOR_EMS_TRF_REF_CASE_STS       CASE
  ,SOR_EMS_TAM_TNCY_AGRMT_STS    TAM
  ,SOR_EMS_TAM_TNCY_AGRMT  TA
  ,(SELECT PREV_CUST_KEY, PREV_HSE_SRVC_APLY_KEY, RVS_DOC_DATE
  FROM SOR_EMS_PAL_PRH_INTK_SCHD_STS INTK
  WHERE 
  INTK_TYPE_CODE IN ('ITR', 'ITR-S')
  AND INTK_SCHD_STS_CODE = 'OFACPT'
  AND TO_CHAR(RVS_DOC_DATE,'YYYYMM') = '$$v_rpt_mth'
  AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN BGN_DATE AND END_DATE
  ) INTK
WHERE 
  CASE.TNCY_AGRMT_KEY = TAM.TNCY_AGRMT_KEY
AND CASE.REF_CASE_KEY = TRC.REF_CASE_KEY
  AND TA.TNCY_AGRMT_KEY = TAM.TNCY_AGRMT_KEY
  AND TA.CUST_KEY = INTK.PREV_CUST_KEY
  AND TA.HSE_SRVC_APLY_KEY = INTK.PREV_HSE_SRVC_APLY_KEY
  and tam.TNCY_AGRMT_TM_STS_CODE <> 'C'
  AND add_months(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1 BETWEEN CASE.BGN_DATE AND CASE.END_DATE
  AND add_months(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1 BETWEEN TAM.BGN_DATE AND TAM.END_DATE
  AND NOT EXISTS 
  (SELECT 1
  FROM SOR_EMS_PHA_APLY_STS APLY
  WHERE   TRC.REF_CASE_BK = APLY.REF_CASE_KEY 
  AND add_months(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1 BETWEEN BGN_DATE AND END_DATE)
UNION
SELECT distinct
  TAM.UNIT_KEY             -- ORIGINAL ADDRESS
  ,DECODE(OPR_TYPE_CODE,       -- TRANSFER TYPE CODE
  '6','XTR',
  '7','INH',
  '9','STR',
  '10','TRW',
  '11','OCR',
  '13','OCR',
  '14','HFT',
  '15','HFT')
  ,NULL                        -- TRANSFER SUB-TYPE CODE
  ,NULL                        -- TRANSFER REASON
FROM
  SOR_EMS_PHA_APLY      APLY
  ,SOR_EMS_PHA_APLY_STS	 PAS
  ,SOR_EMS_TAM_TNCY_AGRMT_STS   TAM
  ,SOR_EMS_POR_OPR          OPR
  ,SOR_EMS_POR_OPR_STS          OPRS
  ,(SELECT HSE_SRVC_APLY_KEY, TNCY_AGRMT_CMNC_DATE, TNCY_AGRMT_TM_STS_CODE
  FROM
  SOR_EMS_TAM_TNCY_AGRMT_STS TAS, SOR_EMS_TAM_TNCY_AGRMT TA
  WHERE 
  TA.TNCY_AGRMT_KEY = TAS.TNCY_AGRMT_KEY
  AND TO_CHAR(TNCY_AGRMT_CMNC_DATE,'YYYYMM') = '$$v_rpt_mth'
  AND TNCY_AGRMT_TM_STS_CODE IN ('A','P')
  AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN BGN_DATE AND END_DATE
  ) TAM_NEW
WHERE
  PAS.APLY_KEY = APLY.APLY_KEY
  AND PAS.TNCY_AGRMT_KEY = TAM.TNCY_AGRMT_KEY
  AND APLY.HSE_SRVC_APLY_KEY = TAM_NEW.HSE_SRVC_APLY_KEY
  AND OPR.OPR_CODE = PAS.OPR_CODE
  AND OPR.OPR_KEY = OPRS.OPR_KEY
  AND PAS.REF_CASE_KEY IS NULL
  AND OPRS.OPR_TYPE_CODE IN ('6', '7', '9', '10', '11', '13', '14', '15')
  and tam.TNCY_AGRMT_TM_STS_CODE <> 'C'
 AND PAS.PRH_APLY_STG_CODE || PAS.PRH_APLY_STS_CODE = '8P'
  AND add_months(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1 BETWEEN PAS.BGN_DATE AND PAS.END_DATE
  AND add_months(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1 BETWEEN OPRS.BGN_DATE AND OPRS.END_DATE
  AND add_months(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1 BETWEEN TAM.BGN_DATE AND TAM.END_DATE;

-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_EMS_POR_OPR_STS
select 
  tam_sts.UNIT_KEY,                
  OPR_TYPE_CODE,                                   
  PRH_APLY_STS_UPD_DATE ,           
  PRH_APLY_STG_UPD_DATE,
  null as HSE_SRVC_APLY_CRE_DATE,
  aply_sts.APLY_KEY,
  aply_sts.PRH_APLY_STG_CODE,
  aply_sts.PRH_APLY_STS_CODE,
  OPR.OPR_KEY 
from                                                                                                       
  SOR_EMS_PHA_APLY         aply,                                                                           
  SOR_EMS_PHA_APLY_STS     aply_sts,                                                                       
  SOR_EMS_POR_OPR          opr,                                                                            
  SOR_EMS_POR_OPR_STS      opr_sts,                                                                        
  SOR_EMS_TAM_TNCY_AGRMT_STS tam_sts                                                     
where                                                                                                      
  aply.APLY_KEY = aply_sts.APLY_KEY and                                                                    
  aply_sts.REF_CASE_KEY is null and                                                                                               
  opr.OPR_KEY = opr_sts.OPR_KEY and                                                                        
  opr.OPR_CODE = aply_sts.OPR_CODE and                                                                     
  opr_sts.OPR_TYPE_CODE in ('6', '7', '9', '10', '11', '13', '14', '15') and  
  aply_sts.PRH_APLY_STG_CODE || aply_sts.PRH_APLY_STS_CODE not in ('3C', '8P') and                           
  tam_sts.TNCY_AGRMT_KEY = aply_sts.TNCY_AGRMT_KEY and                                                       
  tam_sts.TNCY_AGRMT_TM_STS_CODE in ('P', 'A', 'I') and                                                    
  ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1) - 1 BETWEEN aply_sts.BGN_DATE AND aply_sts.END_DATE and
  ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1) - 1 BETWEEN opr_sts.BGN_DATE AND opr_sts.END_DATE and  
  ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1) - 1 BETWEEN tam_sts.BGN_DATE AND tam_sts.END_DATE;

-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_EMS_TRF_REF_CASE1
select distinct
  tam_sts.UNIT_KEY,   
  case_sts.REF_CASE_TYPE_CODE, 
  case_sts.OR_TYPE_CODE,       
  case_sts.TFR_RSN_CODE,       
  PRH_APLY_STS_UPD_DATE,       
  PRH_APLY_STG_UPD_DATE,       
  REF_CASE_STS_UPD_DATE,       
  case.REF_CASE_KEY,           
  aply_sts.APLY_KEY,           
  aply_sts.PRH_APLY_STG_CODE,
  aply_sts.PRH_APLY_STS_CODE, 
  case_sts.REF_cASE_STS_CODE,  
  case_sts.LU_STS_CODE
from 
  SOR_EMS_TRF_REF_CASE       case,
  SOR_EMS_TRF_REF_CASE_STS   case_sts,
  (select APLY_KEY, PRH_APLY_STG_CODE, PRH_APLY_STS_CODE
, REF_CASE_KEY, PRH_APLY_STS_UPD_DATE, PRH_APLY_STG_UPD_DATE
   from SOR_EMS_PHA_APLY_STS
   where ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1) - 1 BETWEEN BGN_DATE AND END_DATE
  ) aply_sts,
  SOR_EMS_TAM_TNCY_AGRMT_STS tam_sts
where 
  case.REF_CASE_KEY = case_sts.REF_cASE_KEY and
  case.REF_CASE_BK = aply_sts.REF_CASE_KEY (+) and
  ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1) - 1 BETWEEN case_sts.BGN_DATE AND case_sts.END_DATE and
  case_sts.TNCY_AGRMT_KEY = tam_sts.TNCY_AGRMT_KEY and
  tam_sts.TNCY_AGRMT_TM_STS_CODE in ('P', 'A', 'I') and
  ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1) - 1 BETWEEN tam_sts.BGN_DATE AND tam_sts.END_DATE;

-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_EMS_PHA_APLY
SELECT DISTINCT                                                                                       
	TAM_STS.UNIT_KEY
	, OPR_TYPE_CODE
	, CMM_STS.HSE_SRVC_APLY_CRE_DATE
	, APLY_STS.APLY_KEY
	, APLY.APLY_KEY
	, OPR.OPR_KEY
FROM                                                                                                       
	SOR_EMS_PHA_APLY APLY
	, SOR_EMS_PHA_APLY_STS APLY_STS
	, SOR_EMS_POR_OPR OPR
	, SOR_EMS_POR_OPR_STS OPR_STS
	, SOR_EMS_TAM_TNCY_AGRMT_STS TAM_STS
	, SOR_EMS_CMM_HSE_SRVC_APLY_STS CMM_STS                                                                  
WHERE                                                                                                      
	APLY.APLY_KEY = APLY_STS.APLY_KEY 
	AND APLY_STS.REF_CASE_KEY IS NULL 
	AND OPR.OPR_KEY = OPR_STS.OPR_KEY 
	AND OPR.OPR_CODE = APLY_STS.OPR_CODE 
	AND OPR_STS.OPR_TYPE_CODE IN ('6', '7', '9', '10', '11', '13', '14', '15') 
	AND TAM_STS.TNCY_AGRMT_KEY = APLY_STS.TNCY_AGRMT_KEY 
	AND TAM_STS.TNCY_AGRMT_TM_STS_CODE IN ('P', 'A', 'I') 
	AND APLY.HSE_SRVC_APLY_KEY = CMM_STS.HSE_SRVC_APLY_KEY 
	AND TO_CHAR(CMM_STS.HSE_SRVC_APLY_CRE_DATE, 'YYYYMM') = '$$v_rpt_mth'
	AND (
		ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1) - 1 BETWEEN APLY_STS.BGN_DATE AND APLY_STS.END_DATE 
		OR NOT EXISTS 
			(
				SELECT 
					NULL 
				FROM 
					SOR_EMS_PHA_APLY_STS
				WHERE 
					BGN_DATE > APLY_STS.BGN_DATE
					AND REF_CASE_KEY = APLY_STS.REF_CASE_KEY
			)
		)
	AND ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1) - 1 BETWEEN OPR_STS.BGN_DATE AND OPR_STS.END_DATE 
	AND ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1) - 1 BETWEEN TAM_STS.BGN_DATE AND TAM_STS.END_DATE 
	AND ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1) - 1 BETWEEN CMM_STS.BGN_DATE AND CMM_STS.END_DATE;

-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_EMS_TRF_REF_CASE
SELECT DISTINCT
	TAM_STS.UNIT_KEY
	, CASE_STS.REF_CASE_TYPE_CODE
	, CASE_STS.OR_TYPE_CODE
	, CASE_STS.TFR_RSN_CODE
	, CASE_STS.REF_CASE_CRE_DATE
	, CASE1.REF_CASE_KEY
	, APLY_STS.APLY_KEY
FROM 
	SOR_EMS_TRF_REF_CASE CASE1
	, SOR_EMS_TRF_REF_CASE_STS CASE_STS
	, SOR_EMS_TAM_TNCY_AGRMT_STS TAM_STS
	, (
		SELECT DISTINCT 
			APLY_KEY
			, REF_CASE_KEY
		FROM 
			SOR_EMS_PHA_APLY_STS
		WHERE 
			ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1) - 1 BETWEEN BGN_DATE AND END_DATE
	) APLY_STS
WHERE 
	CASE1.REF_CASE_KEY = CASE_STS.REF_CASE_KEY 
	AND CASE1.REF_CASE_BK = APLY_STS.REF_CASE_KEY (+) 
	AND CASE_STS.TNCY_AGRMT_KEY = TAM_STS.TNCY_AGRMT_KEY 
	AND	TAM_STS.TNCY_AGRMT_TM_STS_CODE IN ('P', 'A', 'I') 
	AND TO_CHAR(CASE_STS.REF_CASE_CRE_DATE, 'YYYYMM') = '$$v_rpt_mth' 
	AND (
		ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1) - 1 BETWEEN CASE_STS.BGN_DATE AND CASE_STS.END_DATE 
		OR NOT EXISTS 
			(
				SELECT 
					NULL 
				FROM 
					SOR_EMS_TRF_REF_CASE_STS 
				WHERE 
					BGN_DATE > CASE_STS.BGN_DATE
					AND REF_CASE_KEY = CASE_STS.REF_CASE_KEY
			)
		)
	AND ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1) - 1 BETWEEN TAM_STS.BGN_DATE AND TAM_STS.END_DATE;

