SELECT 
DDS_HRCHY_EMS_EST.EST_SCD_KEY as EST_SCD_KEY, 
DDS_HRCHY_EMS_EST.RGN_KEY as RGN_KEY, 
DDS_HRCHY_EMS_EST.RGN_CODE as RGN_CODE, 
DDS_HRCHY_EMS_EST.RGN_ENG_NAME as RGN_ENG_NAME, 
DDS_HRCHY_EMS_EST.MGT_DSTR_KEY as MGT_DSTR_KEY, 
DDS_HRCHY_EMS_EST.MGT_DSTR_CODE as MGT_DSTR_CODE, 
DDS_HRCHY_EMS_EST.MGT_DSTR_ENG_NAME as MGT_DSTR_ENG_NAME, 
DDS_HRCHY_EMS_EST.DTMO_KEY as DTMO_KEY, 
DDS_HRCHY_EMS_EST.DTMO_CODE as DTMO_CODE, 
DDS_HRCHY_EMS_EST.DTMO_ENG_NAME as DTMO_ENG_NAME, 
DDS_HRCHY_EMS_EST.EST_CODE as EST_CODE, 
DDS_HRCHY_EMS_EST.EST_TYPE_CODE as EST_TYPE_CODE, 
DDS_HRCHY_EMS_EST.EST_ENG_NAME as EST_ENG_NAME, 
DDS_HRCHY_EMS_EST.EST_CHI_NAME as EST_CHI_NAME, 
DDS_HRCHY_EMS_EST.BGN_DATE as BGN_DATE, 
DDS_HRCHY_EMS_EST.END_DATE as END_DATE, DDS_HRCHY_EMS_EST.EST_KEY as EST_KEY 
FROM DDS_HRCHY_EMS_EST
WHERE add_months(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1 between DDS_HRCHY_EMS_EST.BGN_DATE AND DDS_HRCHY_EMS_EST.END_DATE;

