-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_HSM_UNIT
SELECT 
	NVL(A.UNIT_ADDR_CODE, 0) AS UNIT_ADDR_CODE
	, NVL(A.UNIT_KEY, 0) AS UNIT_KEY
	, NVL(B.MAX_UNIT_HEAD_CNT, 0) AS MAX_UNIT_HEAD_CNT
	, NVL(B.MIN_UNIT_HEAD_CNT, 0) AS MIN_UNIT_HEAD_CNT
	, NVL(A.UNIT_IFA_AREA, 0) AS UNIT_IFA_AREA
	, NVL(A.UNIT_TYPE_CODE, 0) AS UNIT_TYPE_CODE
	, INDICATOR
	, A.HSE_UNIT_CSL_VCNCY_IND AS CV
	, A.UNIT_TAKE_OVER_DATE
	, A.HSE_UNIT_TM_VOID_STS_BGN_DATE
      , VCNT_IND
FROM
	EIS_HA_PRH_RNTL_UNIT
LEFT OUTER JOIN
	(
		SELECT 
			SOR_HSM_UNIT.UNIT_ADDR_CODE
			, SOR_HSM_UNIT.UNIT_KEY
			, SOR_EMS_HSM_PRH_UNIT_STS.UNIT_TAKE_OVER_DATE
			, SOR_HSM_UNIT_STS.HSE_UNIT_TM_VOID_STS_BGN_DATE
			, SOR_HSM_UNIT.UNIT_IFA_AREA
			, SOR_HSM_UNIT_sts.hse_unit_type_code UNIT_TYPE_CODE
			, SOR_HSM_UNIT.BLK_KEY
			, SOR_HSM_UNIT_STS.HSE_UNIT_CSL_VCNCY_IND
		FROM
			SOR_HSM_UNIT
			, SOR_HSM_UNIT_STS
			, SOR_EMS_HSM_PRH_UNIT_STS
		WHERE 
			SOR_HSM_UNIT.UNIT_KEY = SOR_HSM_UNIT_STS.UNIT_KEY
			AND SOR_HSM_UNIT.UNIT_KEY = SOR_EMS_HSM_PRH_UNIT_STS.UNIT_KEY
			AND ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1 BETWEEN SOR_HSM_UNIT_STS.BGN_DATE AND SOR_HSM_UNIT_STS.END_DATE
			AND ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1 BETWEEN SOR_EMS_HSM_PRH_UNIT_STS.BGN_DATE AND SOR_EMS_HSM_PRH_UNIT_STS.END_DATE
	) A
ON 
	A.UNIT_ADDR_CODE = 'E'||RPAD(TRIM(EIS_HA_PRH_RNTL_UNIT.ESTATE), 4, ' ') || LPAD(TRIM(EIS_HA_PRH_RNTL_UNIT.BLOCK), 3, ' ') || LPAD(TRIM(EIS_HA_PRH_RNTL_UNIT.UNIT), 5, ' ') || NVL(EIS_HA_PRH_RNTL_UNIT.CON_REF, ' ') || NVL(EIS_HA_PRH_RNTL_UNIT.SHRIND, ' ')
LEFT OUTER JOIN
	(
		SELECT 
			SOR_EMS_RFX_ALCT_STD_STS.MAX_UNIT_HEAD_CNT,
			SOR_EMS_RFX_ALCT_STD_STS.MIN_UNIT_HEAD_CNT,
			SOR_EMS_RFX_ALCT_STD.UNIT_IFA_AREA,
			SOR_EMS_RFX_ALCT_STD.UNIT_TYPE_CODE,
			SOR_EMS_RFX_ALCT_STD.BLK_KEY
		FROM 
			SOR_EMS_RFX_ALCT_STD ,SOR_EMS_RFX_ALCT_STD_STS 
		WHERE 
			SOR_EMS_RFX_ALCT_STD.ALCT_STD_KEY = SOR_EMS_RFX_ALCT_STD_STS.ALCT_STD_KEY
			AND UNIT_ALCT_STD_TYPE_CODE = 'O'
			AND ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1 BETWEEN SOR_EMS_RFX_ALCT_STD_STS.BGN_DATE AND SOR_EMS_RFX_ALCT_STD_STS.END_DATE
	) B
ON 
	A.UNIT_TYPE_CODE = B.UNIT_TYPE_CODE AND A.UNIT_IFA_AREA = B.UNIT_IFA_AREA AND A.BLK_KEY = B.BLK_KEY;

