-- [SELECT] Step: read_LKP_DDS_DMNS_UNIT_SIZE
-- Connection: DPA
SELECT 
DDS_DMNS_UNIT_SIZE.UNIT_SIZE_DMNS_KEY as UNIT_SIZE_DMNS_KEY, 
DDS_DMNS_UNIT_SIZE.UNIT_SIZE_CODE as UNIT_SIZE_CODE, 
DDS_DMNS_UNIT_SIZE.UNIT_SIZE_DESP as UNIT_SIZE_DESP, 
DDS_DMNS_UNIT_SIZE.UNIT_SIZE_MIN_AREA as UNIT_SIZE_MIN_AREA, 
DDS_DMNS_UNIT_SIZE.UNIT_SIZE_MAX_AREA as UNIT_SIZE_MAX_AREA 
