WHERE
UNIT_SIZE_CODE IN ('A','B','C','D','E','F','G','H','I','J');

-- [SELECT] Step: read_LKP_RFBH_RLET_UNIT
-- Connection: DPA
SELECT 
	UNIT_KEY AS UNIT_KEY
	, MAX(RFBH_RLET_IND) AS RFBH_RLET_IND
	, MAX(TCHUP_RLET_IND) AS TCHUP_RLET_IND
FROM 
	(
		SELECT 
			U.UNIT_KEY AS UNIT_KEY
			, SUM(CASE WHEN VWOS.WORK_VFRA_TYPE_CODE IN ('L', 'O' ) THEN 1 ELSE 0 END) AS RFBH_RLET_IND
			, SUM(CASE WHEN VWOS.WORK_VFRA_TYPE_CODE = 'T' THEN 1 ELSE 0 END) AS TCHUP_RLET_IND
		FROM 
			(SELECT TNCY_AGRMT_KEY, UNIT_KEY, TNCY_AGRMT_CMNC_DATE, TNCY_AGRMT_TRMT_DATE FROM SOR_EMS_TAM_TNCY_AGRMT_STS WHERE TNCY_AGRMT_TM_STS_CODE IN ('P', 'A', 'I') AND TO_CHAR(TNCY_AGRMT_CMNC_DATE, 'YYYYMM') = '$$v_rpt_mth' AND ADD_MONTHS(TO_DATE('$$v_snsh_date', 'YYYYMMDD'), 1) - 1 BETWEEN BGN_DATE AND END_DATE) TA	
			, (SELECT UNIT_KEY, UNIT_ADDR_CODE FROM SOR_HSM_UNIT WHERE SUBSTR(UNIT_ADDR_CODE,1,2) != 'E9') U
			, (SELECT WORK_ORD_KEY FROM SOR_WKM_MNR_WORK_ORD) VWO
			, (SELECT WORK_ADDR_CODE, WORK_CMPLT_CERT_DATE, WORK_VFRA_TYPE_CODE, WORK_ORD_KEY, WORK_STS_CODE FROM SOR_WKM_VAR_MNR_WORK_ORD_STS WHERE TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN BGN_DATE AND END_DATE) VWOS
			, (SELECT WORK_ORD_KEY, WORK_DTL_KEY FROM SOR_WKM_MNR_WORK_DTL) WOD
			, (SELECT WORK_DTL_KEY, WORK_ISS_DATE FROM SOR_WKM_VAR_MNR_WORK_DTL_STS WHERE TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN BGN_DATE AND END_DATE) WODS
		WHERE
			TA.UNIT_KEY = U.UNIT_KEY
			AND TRIM(VWOS.WORK_ADDR_CODE) = TRIM(U.UNIT_ADDR_CODE)
			AND VWO.WORK_ORD_KEY = VWOS.WORK_ORD_KEY
			AND VWO.WORK_ORD_KEY = WOD.WORK_ORD_KEY
			AND WOD.WORK_DTL_KEY = WODS.WORK_DTL_KEY
			AND VWOS.WORK_CMPLT_CERT_DATE < TA.TNCY_AGRMT_CMNC_DATE
			AND NOT EXISTS
				( 
					SELECT 
						NULL
					FROM 
						(SELECT TNCY_AGRMT_KEY, UNIT_KEY, TNCY_AGRMT_CMNC_DATE FROM SOR_EMS_TAM_TNCY_AGRMT_STS WHERE TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN BGN_DATE AND END_DATE) TA3
					WHERE 
						TA3.UNIT_KEY = TA.UNIT_KEY
						AND TA3.TNCY_AGRMT_CMNC_DATE < TA.TNCY_AGRMT_CMNC_DATE
						AND TA3.TNCY_AGRMT_CMNC_DATE > WODS.WORK_ISS_DATE
				)
			AND NOT EXISTS 
				(
					SELECT 
						NULL
					FROM 
						(SELECT TNCY_AGRMT_KEY, UNIT_KEY, TNCY_AGRMT_TM_TRMT_DATE FROM SOR_EMS_TAM_TNCY_AGRMT_STS WHERE TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN BGN_DATE AND END_DATE) TA2
					WHERE 
						TA2.UNIT_KEY = TA.UNIT_KEY
						AND TA2.TNCY_AGRMT_TM_TRMT_DATE + 1 = TA.TNCY_AGRMT_CMNC_DATE
				)
			AND EXISTS
				(
					SELECT 
						1
					FROM 
						(SELECT TNCY_AGRMT_KEY, UNIT_KEY, TNCY_AGRMT_TM_TRMT_DATE FROM SOR_EMS_TAM_TNCY_AGRMT_STS WHERE TNCY_AGRMT_TM_TRMT_DATE >= TO_DATE('20080201', 'YYYYMMDD') AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN BGN_DATE AND END_DATE) TA2
					WHERE 
						TA2.UNIT_KEY = TA.UNIT_KEY
						AND (TA2.TNCY_AGRMT_TM_TRMT_DATE IS NOT NULL AND TA2.TNCY_AGRMT_TM_TRMT_DATE < TA.TNCY_AGRMT_CMNC_DATE)
				)
		GROUP BY 
			U.UNIT_KEY
	UNION
		SELECT
			WOD.UNIT_KEY
			, SUM(CASE WHEN WOD.WORK_VFRA_TYPE_CODE IN ('L', 'O') THEN 1 ELSE 0 END) AS RFBH_RLET_IND
			, SUM(CASE WHEN WOD.WORK_VFRA_TYPE_CODE = 'T' THEN 1 ELSE 0 END) AS TCHUP_RLET_IND
		FROM
			(
			SELECT
				HSU.UNIT_KEY
				, VWO.WORK_ADDR_CODE
				, VWO.WORK_VFRA_TYPE_CODE
				, VWO.WORK_CMPLT_CERT_DATE
				, WOD.WORK_ISS_DATE
			FROM
				(SELECT UNIT_KEY, TRIM(UNIT_ADDR_CODE) AS UNIT_ADDR_CODE FROM SOR_HSM_UNIT) HSU
				, (SELECT WORK_ORD_KEY, TRIM(WORK_ADDR_CODE) AS WORK_ADDR_CODE, WORK_VFRA_TYPE_CODE, WORK_CMPLT_CERT_DATE FROM SOR_WKM_VAR_MNR_WORK_ORD_STS VWOS WHERE WORK_VFRA_TYPE_CODE IN ('L', 'O', 'T') AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN BGN_DATE AND END_DATE) VWO
				, (SELECT WOD.WORK_ORD_KEY, WODS.WORK_ISS_DATE FROM SOR_WKM_MNR_WORK_DTL WOD, (SELECT WORK_DTL_KEY, WORK_ISS_DATE FROM SOR_WKM_VAR_MNR_WORK_DTL_STS WHERE TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN BGN_DATE AND END_DATE) WODS WHERE WOD.WORK_DTL_KEY = WODS.WORK_DTL_KEY) WOD
			WHERE
				VWO.WORK_ORD_KEY = WOD.WORK_ORD_KEY
				AND HSU.UNIT_ADDR_CODE = VWO.WORK_ADDR_CODE
			) WOD
		WHERE
			EXISTS
			(
				SELECT 
					1
				FROM
					(SELECT UNIT_KEY FROM SOR_HSM_UNIT) HSU
					, (SELECT ADTN.TNCY_AGRMT_KEY, ADTN.UNIT_KEY FROM SOR_EMS_TAM_ADTN_ROOM ADTN, (SELECT ADTN_ROOM_KEY FROM SOR_EMS_TAM_ADTN_ROOM_STS WHERE TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN BGN_DATE AND END_DATE) ADTS WHERE ADTN.ADTN_ROOM_KEY = ADTS.ADTN_ROOM_KEY) ADTN
					, (SELECT TNCY_AGRMT_KEY, TNCY_AGRMT_CMNC_DATE FROM SOR_EMS_TAM_TNCY_AGRMT_STS WHERE TO_CHAR(TNCY_AGRMT_CMNC_DATE, 'YYYYMM') = '$$v_rpt_mth' AND TNCY_AGRMT_TM_STS_CODE IN ('P', 'A', 'I')  AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN BGN_DATE AND END_DATE) TAMS
				WHERE
					HSU.UNIT_KEY = ADTN.UNIT_KEY
					AND TAMS.TNCY_AGRMT_KEY = ADTN.TNCY_AGRMT_KEY
					AND (WOD.UNIT_KEY = HSU.UNIT_KEY AND WOD.WORK_CMPLT_CERT_DATE < TAMS.TNCY_AGRMT_CMNC_DATE)
					AND 
						NOT EXISTS
						( 
							SELECT 
								NULL
							FROM 
								(SELECT UNIT_KEY FROM SOR_HSM_UNIT) BHSU
								, (SELECT ADTN.TNCY_AGRMT_KEY, ADTN.UNIT_KEY FROM SOR_EMS_TAM_ADTN_ROOM ADTN, (SELECT ADTN_ROOM_KEY FROM SOR_EMS_TAM_ADTN_ROOM_STS WHERE TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN BGN_DATE AND END_DATE) ADTS WHERE ADTN.ADTN_ROOM_KEY = ADTS.ADTN_ROOM_KEY) BADT
								, (SELECT TNCY_AGRMT_KEY, TNCY_AGRMT_CMNC_DATE FROM SOR_EMS_TAM_TNCY_AGRMT_STS WHERE TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN BGN_DATE AND END_DATE) BTAM
							WHERE 
								BHSU.UNIT_KEY = BADT.UNIT_KEY
								AND BTAM.TNCY_AGRMT_KEY = BADT.TNCY_AGRMT_KEY
								AND BADT.UNIT_KEY = ADTN.UNIT_KEY
								AND BTAM.TNCY_AGRMT_CMNC_DATE < TAMS.TNCY_AGRMT_CMNC_DATE
								AND BTAM.TNCY_AGRMT_CMNC_DATE > WOD.WORK_ISS_DATE
						)
					AND 
						NOT EXISTS
						(
							SELECT 
								NULL
							FROM  
								(SELECT UNIT_KEY FROM SOR_HSM_UNIT) CHSU
								, (SELECT ADTN.TNCY_AGRMT_KEY, ADTN.UNIT_KEY FROM SOR_EMS_TAM_ADTN_ROOM ADTN, (SELECT ADTN_ROOM_KEY FROM SOR_EMS_TAM_ADTN_ROOM_STS WHERE TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN BGN_DATE AND END_DATE) ADTS WHERE ADTN.ADTN_ROOM_KEY = ADTS.ADTN_ROOM_KEY) CADT
								, (SELECT TNCY_AGRMT_KEY, TNCY_AGRMT_TM_TRMT_DATE FROM SOR_EMS_TAM_TNCY_AGRMT_STS WHERE TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN BGN_DATE AND END_DATE) CTAM
							WHERE 
								CHSU.UNIT_KEY = CADT.UNIT_KEY
								AND CTAM.TNCY_AGRMT_KEY = CADT.TNCY_AGRMT_KEY
								AND CADT.UNIT_KEY = ADTN.UNIT_KEY
								AND CTAM.TNCY_AGRMT_TM_TRMT_DATE + 1 = TAMS.TNCY_AGRMT_CMNC_DATE
						)
					AND 
						EXISTS
						(
							SELECT 
								1
							FROM  
								(SELECT UNIT_KEY FROM SOR_HSM_UNIT) CHSU
								, (SELECT ADTN.TNCY_AGRMT_KEY, ADTN.UNIT_KEY FROM SOR_EMS_TAM_ADTN_ROOM ADTN, (SELECT ADTN_ROOM_KEY FROM SOR_EMS_TAM_ADTN_ROOM_STS WHERE TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN BGN_DATE AND END_DATE) ADTS WHERE ADTN.ADTN_ROOM_KEY = ADTS.ADTN_ROOM_KEY) CADT
								, (SELECT TNCY_AGRMT_KEY, TNCY_AGRMT_TM_TRMT_DATE FROM SOR_EMS_TAM_TNCY_AGRMT_STS WHERE TNCY_AGRMT_TM_TRMT_DATE >= TO_DATE('20080201', 'YYYYMMDD') AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN BGN_DATE AND END_DATE) CTAM
							WHERE 
								CHSU.UNIT_KEY = CADT.UNIT_KEY
								AND CTAM.TNCY_AGRMT_KEY = CADT.TNCY_AGRMT_KEY
								AND CADT.UNIT_KEY = ADTN.UNIT_KEY
								AND (CTAM.TNCY_AGRMT_TM_TRMT_DATE IS NOT NULL AND CTAM.TNCY_AGRMT_TM_TRMT_DATE < TAMS.TNCY_AGRMT_CMNC_DATE)
						)
			)
		GROUP BY
			WOD.UNIT_KEY
	)
GROUP BY 
	UNIT_KEY;

-- [SELECT] Step: read_LKP_RLET_UNIT
-- Connection: DPA
SELECT 
	UNIT_KEY AS UNIT_KEY
	, MAX(RLET_UNIT_IND) AS RLET_UNIT_IND 
FROM 
	(
		SELECT 
			T2.UNIT_KEY AS UNIT_KEY
			, COUNT(DISTINCT T2.UNIT_KEY) AS RLET_UNIT_IND
		FROM 
			(SELECT TNCY_AGRMT_KEY, UNIT_KEY, TNCY_AGRMT_CMNC_DATE FROM SOR_EMS_TAM_TNCY_AGRMT_STS WHERE TNCY_AGRMT_TM_STS_CODE IN  ('P', 'A', 'I') AND TO_CHAR(TNCY_AGRMT_CMNC_DATE, 'YYYYMM') = '$$v_rpt_mth' AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN BGN_DATE AND END_DATE) T2	
		WHERE
			NOT EXISTS (
				SELECT 	
					NULL
				FROM 
					(SELECT TNCY_AGRMT_KEY, UNIT_KEY, TNCY_AGRMT_TM_TRMT_DATE FROM SOR_EMS_TAM_TNCY_AGRMT_STS WHERE TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN BGN_DATE AND END_DATE) T9
				WHERE   
					T9.UNIT_KEY = T2.UNIT_KEY
					AND T2.TNCY_AGRMT_CMNC_DATE = T9.TNCY_AGRMT_TM_TRMT_DATE + 1
			)
			AND EXISTS (
				SELECT 	
					1
				FROM 
					(SELECT TNCY_AGRMT_KEY, UNIT_KEY, TNCY_AGRMT_TM_TRMT_DATE FROM SOR_EMS_TAM_TNCY_AGRMT_STS WHERE TNCY_AGRMT_TM_TRMT_DATE >= TO_DATE('20080201', 'YYYYMMDD') AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN BGN_DATE AND END_DATE) T9
				WHERE   
					T9.UNIT_KEY = T2.UNIT_KEY
					AND (T9.TNCY_AGRMT_TM_TRMT_DATE IS NOT NULL AND T2.TNCY_AGRMT_CMNC_DATE > T9.TNCY_AGRMT_TM_TRMT_DATE)
			)
		GROUP BY 
			T2.UNIT_KEY
	UNION
		SELECT 
			ADTN.UNIT_KEY
			, COUNT(DISTINCT ADTN.UNIT_KEY) AS RLET_UNIT_IND
		FROM 
			(SELECT ADTN_ROOM_KEY, UNIT_KEY, TNCY_AGRMT_KEY FROM SOR_EMS_TAM_ADTN_ROOM) ADTN
			, (SELECT ADTN_ROOM_KEY FROM SOR_EMS_TAM_ADTN_ROOM_STS WHERE TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD') BETWEEN BGN_DATE AND END_DATE) ADTS
			, (SELECT TNCY_AGRMT_KEY, TNCY_AGRMT_CMNC_DATE FROM SOR_EMS_TAM_TNCY_AGRMT_STS WHERE TNCY_AGRMT_TM_STS_CODE IN  ('P', 'A', 'I') AND TO_CHAR(TNCY_AGRMT_CMNC_DATE, 'YYYYMM') = '$$v_rpt_mth' AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN BGN_DATE AND END_DATE) T
		WHERE
			ADTN.TNCY_AGRMT_KEY = T.TNCY_AGRMT_KEY
			AND ADTN.ADTN_ROOM_KEY = ADTS.ADTN_ROOM_KEY
			AND NOT EXISTS (
				SELECT 
					NULL
				FROM 
					(SELECT ADTN_ROOM_KEY, UNIT_KEY, TNCY_AGRMT_KEY FROM SOR_EMS_TAM_ADTN_ROOM) ADTN2
					, (SELECT ADTN_ROOM_KEY FROM SOR_EMS_TAM_ADTN_ROOM_STS WHERE TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD') BETWEEN BGN_DATE AND END_DATE) ADTS2
					, (SELECT TNCY_AGRMT_KEY, TNCY_AGRMT_TM_TRMT_DATE FROM SOR_EMS_TAM_TNCY_AGRMT_STS WHERE TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN BGN_DATE AND END_DATE) T2
				WHERE   
					ADTN2.TNCY_AGRMT_KEY = T2.TNCY_AGRMT_KEY
					AND ADTN2.ADTN_ROOM_KEY = ADTS2.ADTN_ROOM_KEY
					AND ADTN.UNIT_KEY = ADTN2.UNIT_KEY
					AND T.TNCY_AGRMT_CMNC_DATE = T2.TNCY_AGRMT_TM_TRMT_DATE + 1
			)
			AND EXISTS (
				SELECT 
					1
				FROM 
					(SELECT ADTN_ROOM_KEY, UNIT_KEY, TNCY_AGRMT_KEY FROM SOR_EMS_TAM_ADTN_ROOM) ADTN2
					, (SELECT ADTN_ROOM_KEY FROM SOR_EMS_TAM_ADTN_ROOM_STS WHERE TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD') BETWEEN BGN_DATE AND END_DATE) ADTS2
					, (SELECT TNCY_AGRMT_KEY, TNCY_AGRMT_TM_TRMT_DATE FROM SOR_EMS_TAM_TNCY_AGRMT_STS WHERE TNCY_AGRMT_TM_TRMT_DATE >= TO_DATE('20080201', 'YYYYMMDD') AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN BGN_DATE AND END_DATE) T2
				WHERE   
					ADTN2.TNCY_AGRMT_KEY = T2.TNCY_AGRMT_KEY
					AND ADTN2.ADTN_ROOM_KEY = ADTS2.ADTN_ROOM_KEY
					AND ADTN.UNIT_KEY = ADTN2.UNIT_KEY
					AND (T2.TNCY_AGRMT_TM_TRMT_DATE IS NOT NULL AND T.TNCY_AGRMT_CMNC_DATE > T2.TNCY_AGRMT_TM_TRMT_DATE)
			)
		GROUP BY 
			ADTN.UNIT_KEY 
	)
GROUP BY UNIT_KEY;

-- [SELECT] Step: read_LKP_UNIT_ADVS_ENV_CODE_IND
-- Connection: DPA
SELECT UNIT_ADDR_CODE as UNIT_ADDR_CODE, 
DECODE( COUNT(1), 0, 'N', 'Y' ) as UNIT_ADVS_ENV_CODE_IND
FROM SOR_HSM_UNIT U, SOR_HSM_UNIT_STS US, 
SOR_EMS_HSM_UNIT_SCND_ENV E, SOR_EMS_HSM_UNIT_SCND_ENV_STS ES
WHERE U.UNIT_KEY = E.UNIT_KEY
and U.UNIT_KEY = US.UNIT_KEY
and ES.UNIT_SCND_ENV_KEY = E.UNIT_SCND_ENV_KEY
AND E.UNIT_SCND_ENV_CODE IN ( '31', '32', '33', '35', '36', '37','40', '41', '42', '43', '44', '45' )
and add_months(to_date('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1 between ES.BGN_DATE and ES.END_DATE
and add_months(to_date('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1 between US.BGN_DATE and US.END_DATE
group by UNIT_ADDR_CODE;

-- [SELECT] Step: read_LKP_DSTR_EST
-- Connection: DPA
SELECT DIS.EMMS_DSTR_KEY AS DSTR_BRD_DSTR_EMMS_KEY, 
DCH.EMMS_DSTR_KEY AS DSTR_CHC_DSTR_EMMS_KEY, 
E.EST_KEY as EST_KEY, 
B.BLK_KEY as BLK_KEY, 
B.EMMS_BLK_KEY as EMMS_BLK_KEY, 
U.UNIT_ADDR_CODE as UNIT_ADDR_CODE FROM 
(select D.EMMS_DSTR_KEY, EDR.EST_KEY from SOR_HSM_DSTR D, SOR_HSM_EST_DSTR_RLTN EDR
WHERE EDR.DSTR_KEY = D.DSTR_KEY  AND DSTR_TYPE_CODE = 'DCH' 
AND add_months(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1 BETWEEN BGN_DATE AND END_DATE) DCH,
(select D.EMMS_DSTR_KEY, EDR.EST_KEY from SOR_HSM_DSTR D, SOR_HSM_EST_DSTR_RLTN EDR
WHERE EDR.DSTR_KEY = D.DSTR_KEY  AND DSTR_TYPE_CODE = 'DIS'
AND add_months(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1 BETWEEN BGN_DATE AND END_DATE) DIS,
SOR_HSM_UNIT U, 
SOR_HSM_BLK B, 
SOR_HSM_EST E
WHERE E.EST_KEY = DIS.EST_KEY 
AND E.EST_KEY = DCH.EST_KEY
AND U.BLK_KEY = B.BLK_KEY 
AND B.EST_KEY = E.EST_KEY;

-- [SELECT] Step: read_LKP_LAST_TPS_DOT
-- Connection: DPA
SELECT (T.TPS_AGRMT_TRMT_DATE + 1) as LAST_TPS_DOT, UNIT_KEY as UNIT_KEY
FROM SOR_EMS_TOW_TPS_AGRMT_STS T
WHERE T.TPS_AGRMT_EXOWNR_REF_CODE IS NOT NULL
AND T.TPS_TRMT_TYPE_CODE IN ( 'B', 'RS', 'RN' )
and to_date('$$v_snsh_date', 'YYYYMMDD') between bgn_date and end_date
and T.TPS_AGRMT_TRMT_DATE <= add_months(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1;

-- [SELECT] Step: read_LKP_LAST_DOT
-- Connection: DPA
SELECT MAX( TNCY_AGRMT_TM_TRMT_DATE + 1 ) as LAST_DOT, UNIT_KEY as UNIT_KEY
FROM (
SELECT M.TNCY_AGRMT_TM_TRMT_DATE, M.UNIT_KEY
FROM SOR_EMS_TAM_TNCY_AGRMT_STS M
where to_date('$$v_snsh_date', 'YYYYMMDD') between M.bgn_date and M.end_date
and M.TNCY_AGRMT_TM_TRMT_DATE is not null
UNION
SELECT TAS.TNCY_AGRMT_TM_TRMT_DATE, AR.UNIT_KEY
FROM SOR_EMS_TAM_ADTN_ROOM AR, SOR_EMS_TAM_TNCY_AGRMT_STS TAS
WHERE AR.TNCY_AGRMT_KEY = TAS.TNCY_AGRMT_KEY
and TAS.TNCY_AGRMT_TM_TRMT_DATE is not null)
where TNCY_AGRMT_TM_TRMT_DATE <= add_months(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1
group by UNIT_KEY;

-- [SELECT] Step: read_mplt_LKPTRANS
-- Connection: source_db
SELECT 
	SOR_HSM_EST.EST_KEY AS EST_KEY, 
	case when max(MGT_TYPE_CODE) <= 0 and min(MGT_TYPE_CODE) = -1 then 'PSA'
	when min(MGT_TYPE_CODE) >= 0 and max(MGT_TYPE_CODE) = 1  then 'HA'
	when max(MGT_TYPE_CODE) = 0  and min(MGT_TYPE_CODE) = 0   then 'N/A'
	else 'MIXED' end AS MGT_MODE_CODE
FROM
	SOR_HSM_EST, 
	(SELECT DISTINCT SOR_HSM_BLK.EST_KEY, SOR_EMS_HSM_PRH_BLK_STS.BLK_KEY AS BLK_KEY, 
	DECODE(SOR_EMS_HSM_PRH_BLK_STS.MGT_TYPE_CODE, NULL, 0, 'HD', 1, -1) AS MGT_TYPE_CODE
	FROM
		SOR_HSM_BLK,
		SOR_EMS_HSM_PRH_BLK_STS
	WHERE
		ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1)-1 BETWEEN SOR_EMS_HSM_PRH_BLK_STS.BGN_DATE AND SOR_EMS_HSM_PRH_BLK_STS.END_DATE		
		AND SOR_HSM_BLK.BLK_KEY=SOR_EMS_HSM_PRH_BLK_STS.BLK_KEY) MGT_TYPE
WHERE
	SOR_HSM_EST.EST_KEY=MGT_TYPE.EST_KEY
GROUP BY
	SOR_HSM_EST.EST_KEY;

-- [TABLE_READ] Step: read_LKP_DDS_DMNS_EMS_DSTR_BRD_DSTR
-- Table: DDS_DMNS_EMS_DSTR_BRD_DSTR
