-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_EMS_HSM_BLK_5
SELECT 
	TO_NUMBER(SUBSTR('$$v_rpt_mth', 5, 2)) AS SYS_RPT_MTH
	, TO_NUMBER(SUBSTR('$$v_rpt_mth', 1, 4)) AS SYS_RPT_YEAR
	, T1.EST_KEY
	, DIS.EMMS_DSTR_KEY AS DSTR_BRD_EMMS_DSTR_KEY
	, DCH.EMMS_DSTR_KEY AS DSTR_CHC_EMMS_DSTR_KEY 
	, COUNT(*) AS BLK_CNT
FROM
	(SELECT EST_KEY FROM SOR_HSM_EST WHERE EST_CODE LIKE '9%') T1
	, (SELECT BLK_KEY, EMMS_BLK_KEY FROM SOR_HSM_BLK) T2
	, (SELECT A.BLK_KEY, A.BLK_BK, A.EST_KEY FROM SOR_EMS_HSM_BLK A, SOR_EMS_HSM_BLK_STS B WHERE A.BLK_KEY = B.BLK_KEY AND ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1) - 1 BETWEEN BGN_DATE AND END_DATE AND (HSE_BLK_END_DATE IS NULL OR HSE_BLK_END_DATE > ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1) - 1) AND BLK_CMPLT_DATE <= ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1) - 1 AND BLK_HOVR_DATE <= ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1) - 1) T3
	, (SELECT BLK_KEY FROM SOR_EMS_HSM_PRH_BLK_STS WHERE ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1) - 1 BETWEEN BGN_DATE AND END_DATE) T4
	, (SELECT D.EMMS_DSTR_KEY, EDR.EST_KEY FROM SOR_HSM_DSTR D, SOR_HSM_EST_DSTR_RLTN EDR WHERE EDR.DSTR_KEY = D.DSTR_KEY AND DSTR_TYPE_CODE = 'DCH' AND ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1) - 1 BETWEEN BGN_DATE AND END_DATE) DCH
	, (SELECT D.EMMS_DSTR_KEY, EDR.EST_KEY FROM SOR_HSM_DSTR D, SOR_HSM_EST_DSTR_RLTN EDR WHERE EDR.DSTR_KEY = D.DSTR_KEY AND DSTR_TYPE_CODE = 'DIS' AND ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1) - 1 BETWEEN BGN_DATE AND END_DATE) DIS
WHERE
	T1.EST_KEY = T3.EST_KEY
	AND T2.EMMS_BLK_KEY = T3.BLK_BK
	AND T2.BLK_KEY = T4.BLK_KEY
	AND T1.EST_KEY = DIS.EST_KEY 
	AND T1.EST_KEY = DCH.EST_KEY
GROUP BY
	TO_NUMBER(SUBSTR('$$v_rpt_mth', 5, 2))
	, TO_NUMBER(SUBSTR('$$v_rpt_mth', 1, 4))
	, T1.EST_KEY
	, DIS.EMMS_DSTR_KEY
	, DCH.EMMS_DSTR_KEY;

-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_EMS_HSM_BLK_2
SELECT DISTINCT TT2.BLK_KEY FROM
	(SELECT EST_KEY FROM SOR_HSM_EST WHERE EST_CODE LIKE '9%') TT1
	, (SELECT BLK_KEY, EMMS_BLK_KEY FROM SOR_HSM_BLK) TT2
	, (SELECT A.BLK_KEY, A.BLK_BK, A.EST_KEY FROM SOR_EMS_HSM_BLK A, SOR_EMS_HSM_BLK_STS B WHERE A.BLK_KEY = B.BLK_KEY AND ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1) - 1 BETWEEN BGN_DATE AND END_DATE AND (HSE_BLK_END_DATE IS NULL OR HSE_BLK_END_DATE > ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1) - 1) AND BLK_CMPLT_DATE <= ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1) - 1 AND BLK_HOVR_DATE <= ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1) - 1) TT3
	, (SELECT BLK_KEY FROM SOR_EMS_HSM_PRH_BLK_STS WHERE ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1) - 1 BETWEEN BGN_DATE AND END_DATE) TT4
WHERE
	TT1.EST_KEY = TT3.EST_KEY
	AND TT2.EMMS_BLK_KEY = TT3.BLK_BK
	AND TT2.BLK_KEY = TT4.BLK_KEY;

-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_EMS_HSM_BLK_4
SELECT 
	TO_NUMBER(SUBSTR('$$v_rpt_mth', 5, 2)) AS SYS_RPT_MTH
	, TO_NUMBER(SUBSTR('$$v_rpt_mth', 1, 4)) AS SYS_RPT_YEAR
	, HSB.EST_KEY
	, DIS.EMMS_DSTR_KEY AS DSTR_BRD_EMMS_DSTR_KEY
	, DCH.EMMS_DSTR_KEY AS DSTR_CHC_EMMS_DSTR_KEY 
	, HSU.UNIT_TYPE_CODE
	, RAS.MIN_UNIT_HEAD_CNT
	, RAS.MAX_UNIT_HEAD_CNT
	, HSU.UNIT_IFA_AREA
	, COUNT(DISTINCT TAMS.UNIT_KEY) + SUM(NVL(T9.ADTN_ROOM_CNT, 0)) AS RCVR_UNIT_CNT
FROM 
	(SELECT TNCY_AGRMT_KEY, HSE_SRVC_APLY_KEY FROM SOR_EMS_TAM_TNCY_AGRMT) TAM
INNER JOIN
	(
		SELECT 
			TNCY_AGRMT_KEY, UNIT_KEY, TNCY_AGRMT_TM_TRMT_DATE
		FROM 
			SOR_EMS_TAM_TNCY_AGRMT_STS TAMS
		WHERE 
			TNCY_AGRMT_TM_STS_CODE <> 'C' 
			AND TNCY_AGRMT_TM_TRMT_DATE BETWEEN ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), -1) AND ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1) - 1 
			AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN BGN_DATE AND END_DATE
			AND NOT EXISTS (
				SELECT 
					NULL
				FROM 
					SOR_EMS_TAM_TNCY_AGRMT_STS
				WHERE 
					TNCY_AGRMT_TM_STS_CODE <> 'C' 
					AND TNCY_AGRMT_TM_TRMT_DATE BETWEEN ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), -1) AND LAST_DAY(ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), -1)) 
					AND ADD_MONTHS(TO_DATE('$$v_snsh_date', 'YYYYMMDD'), -1) BETWEEN BGN_DATE AND END_DATE
					AND NOT EXISTS (
						SELECT 
							NULL
						FROM 
							(SELECT TNCY_AGRMT_KEY, UNIT_KEY, TNCY_AGRMT_CMNC_DATE FROM SOR_EMS_TAM_TNCY_AGRMT_STS WHERE ADD_MONTHS(TO_DATE('$$v_snsh_date', 'YYYYMMDD'), -1) BETWEEN BGN_DATE AND END_DATE) TMP
						WHERE   
							TMP.UNIT_KEY = SOR_EMS_TAM_TNCY_AGRMT_STS.UNIT_KEY
							AND TMP.TNCY_AGRMT_CMNC_DATE BETWEEN SOR_EMS_TAM_TNCY_AGRMT_STS.TNCY_AGRMT_TM_TRMT_DATE + 1 AND SOR_EMS_TAM_TNCY_AGRMT_STS.TNCY_AGRMT_TM_TRMT_DATE + 30)
					AND TAMS.TNCY_AGRMT_KEY = SOR_EMS_TAM_TNCY_AGRMT_STS.TNCY_AGRMT_KEY
			)
	) TAMS
ON
	TAM.TNCY_AGRMT_KEY = TAMS.TNCY_AGRMT_KEY 
INNER JOIN
	(SELECT UNIT_KEY, BLK_KEY, UNIT_IFA_AREA, UNIT_TYPE_CODE FROM SOR_HSM_UNIT WHERE UPPER(UNIT_ADDR_CODE) LIKE 'E9%') HSU
ON
	TAMS.UNIT_KEY = HSU.UNIT_KEY 
INNER JOIN
	(SELECT BLK_KEY, EST_KEY FROM SOR_HSM_BLK) HSB
ON
	HSU.BLK_KEY = HSB.BLK_KEY
LEFT OUTER JOIN	
	(SELECT RAS.ALCT_STD_KEY, RAS.BLK_KEY, RAS.UNIT_IFA_AREA, RAS.UNIT_TYPE_CODE, RASS.MIN_UNIT_HEAD_CNT, RASS.MAX_UNIT_HEAD_CNT FROM SOR_EMS_RFX_ALCT_STD RAS, SOR_EMS_RFX_ALCT_STD_STS RASS WHERE RAS.ALCT_STD_KEY = RASS.ALCT_STD_KEY AND UNIT_ALCT_STD_TYPE_CODE = 'O' AND ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1) - 1 BETWEEN RASS.BGN_DATE AND RASS.END_DATE) RAS
ON 
	HSU.BLK_KEY = RAS.BLK_KEY AND HSU.UNIT_IFA_AREA = RAS.UNIT_IFA_AREA AND HSU.UNIT_TYPE_CODE = RAS.UNIT_TYPE_CODE
LEFT OUTER JOIN
	(
		SELECT 
			TNCY_AGRMT_KEY
			, COUNT(DISTINCT UNIT_KEY) AS ADTN_ROOM_CNT
		FROM 
			(SELECT ADTN_ROOM_KEY, UNIT_KEY, TNCY_AGRMT_KEY FROM SOR_EMS_TAM_ADTN_ROOM) ADTN
			, (SELECT ADTN_ROOM_KEY FROM SOR_EMS_TAM_ADTN_ROOM_STS WHERE ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1) - 1 BETWEEN BGN_DATE AND END_DATE) ADTS
		WHERE
			ADTN.ADTN_ROOM_KEY = ADTS.ADTN_ROOM_KEY
		GROUP BY TNCY_AGRMT_KEY
	) T9
ON
	TAM.TNCY_AGRMT_KEY = T9.TNCY_AGRMT_KEY
INNER JOIN
	(SELECT D.EMMS_DSTR_KEY, EDR.EST_KEY FROM SOR_HSM_DSTR D, SOR_HSM_EST_DSTR_RLTN EDR WHERE EDR.DSTR_KEY = D.DSTR_KEY AND DSTR_TYPE_CODE = 'DCH' AND ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1) - 1 BETWEEN BGN_DATE AND END_DATE) DCH
ON
	HSB.EST_KEY = DCH.EST_KEY 
INNER JOIN	
	(SELECT D.EMMS_DSTR_KEY, EDR.EST_KEY FROM SOR_HSM_DSTR D, SOR_HSM_EST_DSTR_RLTN EDR WHERE EDR.DSTR_KEY = D.DSTR_KEY AND DSTR_TYPE_CODE = 'DIS' AND ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1) - 1 BETWEEN BGN_DATE AND END_DATE) DIS	
ON
	HSB.EST_KEY = DIS.EST_KEY
WHERE
	NOT EXISTS (
		SELECT 
			NULL
		FROM 
			(SELECT TNCY_AGRMT_KEY, UNIT_KEY, TNCY_AGRMT_CMNC_DATE FROM SOR_EMS_TAM_TNCY_AGRMT_STS WHERE TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN BGN_DATE AND END_DATE) T9
		WHERE   
			T9.UNIT_KEY = TAMS.UNIT_KEY
			AND T9.TNCY_AGRMT_CMNC_DATE BETWEEN TAMS.TNCY_AGRMT_TM_TRMT_DATE + 1 AND TAMS.TNCY_AGRMT_TM_TRMT_DATE + 30)
GROUP BY 
	TO_NUMBER(SUBSTR('$$v_rpt_mth', 5, 2))
	, TO_NUMBER(SUBSTR('$$v_rpt_mth', 1, 4))
	, HSB.EST_KEY
	, DIS.EMMS_DSTR_KEY
	, DCH.EMMS_DSTR_KEY
	, HSU.UNIT_TYPE_CODE
	, RAS.MIN_UNIT_HEAD_CNT
	, RAS.MAX_UNIT_HEAD_CNT
	, HSU.UNIT_IFA_AREA;

-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_EMS_HSM_BLK_3
SELECT 
	TO_NUMBER(SUBSTR('$$v_rpt_mth', 5, 2)) AS SYS_RPT_MTH
	, TO_NUMBER(SUBSTR('$$v_rpt_mth', 1, 4)) AS SYS_RPT_YEAR
	, HSB.EST_KEY
	, DIS.EMMS_DSTR_KEY AS DSTR_BRD_EMMS_DSTR_KEY
	, DCH.EMMS_DSTR_KEY AS DSTR_CHC_EMMS_DSTR_KEY 
	, HSU.UNIT_TYPE_CODE
	, RAS.MIN_UNIT_HEAD_CNT
	, RAS.MAX_UNIT_HEAD_CNT
	, HSU.UNIT_IFA_AREA
	, SUM(0) as RCVR_UNIT_GWL_SIX_MTH_CNT
	, COUNT(TAMS.UNIT_KEY) + SUM(NVL(ADRM.ADTN_ROOM_CNT, 0)) AS RCVR_UNIT_TRWL_SIX_MTH_CNT
FROM 
	(SELECT TNCY_AGRMT_KEY, HSE_SRVC_APLY_KEY, CUST_KEY FROM SOR_EMS_TAM_TNCY_AGRMT) TAM
INNER JOIN
	(
		SELECT 
			TNCY_AGRMT_KEY, UNIT_KEY, TNCY_AGRMT_CMNC_DATE 
		FROM 
			SOR_EMS_TAM_TNCY_AGRMT_STS TAMS
		WHERE 
			TNCY_AGRMT_TM_STS_CODE = 'I' 
			AND TNCY_AGRMT_TM_TRMT_DATE BETWEEN ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), -1) AND ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1) - 1 
			AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN BGN_DATE AND END_DATE
			AND NOT EXISTS (
				SELECT 
					NULL
				FROM 
					SOR_EMS_TAM_TNCY_AGRMT_STS
				WHERE 
					TNCY_AGRMT_TM_STS_CODE = 'I'
					AND TNCY_AGRMT_TM_TRMT_DATE BETWEEN ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), -1) AND LAST_DAY(ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), -1)) 
					AND ADD_MONTHS(TO_DATE('$$v_snsh_date', 'YYYYMMDD'), -1) BETWEEN BGN_DATE AND END_DATE
					AND TAMS.TNCY_AGRMT_KEY = SOR_EMS_TAM_TNCY_AGRMT_STS.TNCY_AGRMT_KEY
			)
		) TAMS
ON
	TAM.TNCY_AGRMT_KEY = TAMS.TNCY_AGRMT_KEY
INNER JOIN
	(SELECT UNIT_KEY, BLK_KEY, UNIT_IFA_AREA, UNIT_TYPE_CODE FROM SOR_HSM_UNIT WHERE UPPER(UNIT_ADDR_CODE) LIKE 'E9%') HSU
ON
	TAMS.UNIT_KEY = HSU.UNIT_KEY
INNER JOIN
	(SELECT BLK_KEY, EST_KEY FROM SOR_HSM_BLK) HSB
ON
	HSU.BLK_KEY = HSB.BLK_KEY
LEFT OUTER JOIN	
	(SELECT RAS.ALCT_STD_KEY, RAS.BLK_KEY, RAS.UNIT_IFA_AREA, RAS.UNIT_TYPE_CODE, RASS.MIN_UNIT_HEAD_CNT, RASS.MAX_UNIT_HEAD_CNT FROM SOR_EMS_RFX_ALCT_STD RAS, SOR_EMS_RFX_ALCT_STD_STS RASS WHERE RAS.ALCT_STD_KEY = RASS.ALCT_STD_KEY AND UNIT_ALCT_STD_TYPE_CODE = 'O' AND ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1) - 1 BETWEEN RASS.BGN_DATE AND RASS.END_DATE) RAS
ON 
	HSU.BLK_KEY = RAS.BLK_KEY AND HSU.UNIT_IFA_AREA = RAS.UNIT_IFA_AREA AND HSU.UNIT_TYPE_CODE = RAS.UNIT_TYPE_CODE
INNER JOIN
	(SELECT APLY_KEY, TNCY_AGRMT_KEY, PRH_APLY_STG_UPD_DATE, PRH_APLY_STS_UPD_DATE FROM SOR_EMS_PHA_APLY_STS WHERE PRH_APLY_STG_CODE = '8' AND PRH_APLY_STS_CODE = 'P' AND ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1) - 1 BETWEEN BGN_DATE AND END_DATE) PHS
ON
	TAM.TNCY_AGRMT_KEY = PHS.TNCY_AGRMT_KEY AND TAMS.TNCY_AGRMT_CMNC_DATE <= PHS.PRH_APLY_STG_UPD_DATE AND TAMS.TNCY_AGRMT_CMNC_DATE <= PHS.PRH_APLY_STS_UPD_DATE
INNER JOIN
	(SELECT APLY_KEY, HSE_SRVC_APLY_KEY FROM SOR_EMS_PHA_APLY) PHA
ON
	PHA.APLY_KEY = PHS.APLY_KEY
INNER JOIN
	(SELECT HSE_SRVC_APLY_KEY FROM SOR_EMS_CMM_HSE_SRVC_APLY_STS WHERE (HSE_SRVC_APLY_NUM LIKE 'L%' OR HSE_SRVC_APLY_NUM LIKE 'A%') AND ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1) - 1 BETWEEN BGN_DATE AND END_DATE) CMM
ON
	PHA.HSE_SRVC_APLY_KEY = CMM.HSE_SRVC_APLY_KEY
INNER JOIN
	(SELECT D.EMMS_DSTR_KEY, EDR.EST_KEY FROM SOR_HSM_DSTR D, SOR_HSM_EST_DSTR_RLTN EDR WHERE EDR.DSTR_KEY = D.DSTR_KEY AND DSTR_TYPE_CODE = 'DCH' AND ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1) - 1 BETWEEN BGN_DATE AND END_DATE) DCH
ON
	HSB.EST_KEY = DCH.EST_KEY 
INNER JOIN	
	(SELECT D.EMMS_DSTR_KEY, EDR.EST_KEY FROM SOR_HSM_DSTR D, SOR_HSM_EST_DSTR_RLTN EDR WHERE EDR.DSTR_KEY = D.DSTR_KEY AND DSTR_TYPE_CODE = 'DIS' AND ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1) - 1 BETWEEN BGN_DATE AND END_DATE) DIS
ON
	HSB.EST_KEY = DIS.EST_KEY
LEFT OUTER JOIN
	(
		SELECT 
			TNCY_AGRMT_KEY
			, COUNT(DISTINCT UNIT_KEY) AS ADTN_ROOM_CNT
		FROM 
			(SELECT ADTN_ROOM_KEY, UNIT_KEY, TNCY_AGRMT_KEY FROM SOR_EMS_TAM_ADTN_ROOM) ADTN
			, (SELECT ADTN_ROOM_KEY FROM SOR_EMS_TAM_ADTN_ROOM_STS WHERE ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1) - 1 BETWEEN BGN_DATE AND END_DATE) ADTS
		WHERE
			ADTN.ADTN_ROOM_KEY = ADTS.ADTN_ROOM_KEY
		GROUP BY TNCY_AGRMT_KEY
	) ADRM
ON
	TAM.TNCY_AGRMT_KEY = ADRM.TNCY_AGRMT_KEY
GROUP BY 
	TO_NUMBER(SUBSTR('$$v_rpt_mth', 5, 2))
	, TO_NUMBER(SUBSTR('$$v_rpt_mth', 1, 4))
	, HSB.EST_KEY
	, DIS.EMMS_DSTR_KEY
	, DCH.EMMS_DSTR_KEY
	, HSU.UNIT_TYPE_CODE
	, RAS.MIN_UNIT_HEAD_CNT
	, RAS.MAX_UNIT_HEAD_CNT
	, HSU.UNIT_IFA_AREA;

-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_EMS_HSM_BLK_1
SELECT
	TO_NUMBER(SUBSTR('$$v_rpt_mth', 5, 2)) AS SYS_RPT_MTH
	, TO_NUMBER(SUBSTR('$$v_rpt_mth', 1, 4)) AS SYS_RPT_YEAR
	, T4.EST_KEY
	, T4.BLK_KEY
	, DIS.EMMS_DSTR_KEY AS DSTR_BRD_EMMS_DSTR_KEY
	, DCH.EMMS_DSTR_KEY AS DSTR_CHC_EMMS_DSTR_KEY 
	, T1.UNIT_TYPE_CODE
	, T5.MIN_UNIT_HEAD_CNT
	, T5.MAX_UNIT_HEAD_CNT
	, T1.UNIT_IFA_AREA
	, SUM(
		CASE WHEN 
			UPPER(T3.HSE_UNIT_TM_STS_CODE) in ('OCPY', 'VCNT', 'TOBETERM') 
			AND (T3.HSE_UNIT_DMLH_DATE IS NULL OR TO_CHAR(T3.HSE_UNIT_DMLH_DATE, 'YYYYMM') > '$$v_rpt_mth')
		THEN 1 ELSE 0 END
	) AS UNIT_CNT
	, SUM(
		CASE WHEN 
			UPPER(T3.HSE_UNIT_TM_STS_CODE) = 'VCNT'
			AND UNIT_ALCT_STS_CODE = 0
		THEN 1 ELSE 0 END
	) AS VCNT_UNIT_CNT
	, SUM(
		CASE WHEN
			UPPER(T3.HSE_UNIT_TM_STS_CODE) = 'VCNT'
			AND UNIT_ALCT_STS_CODE IN (1, 2)
		THEN 1 ELSE 0 END
	) AS UND_OFR_UNIT_CNT
FROM 
	(SELECT UNIT_TYPE_CODE, UNIT_KEY, BLK_KEY, UNIT_IFA_AREA FROM SOR_HSM_UNIT WHERE UPPER(UNIT_ADDR_CODE) LIKE 'E9%') T1
INNER JOIN
	(SELECT UNIT_KEY, UNIT_ALCT_STS_CODE FROM SOR_EMS_HSM_PRH_UNIT_STS WHERE ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1) - 1 BETWEEN BGN_DATE AND END_DATE) T2
ON
	T1.UNIT_KEY = T2.UNIT_KEY 
INNER JOIN
	(SELECT HSE_UNIT_TM_STS_CODE, HSE_UNIT_DMLH_DATE, UNIT_KEY FROM SOR_HSM_UNIT_STS WHERE ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1) - 1 BETWEEN BGN_DATE AND END_DATE AND HSE_UNIT_TM_STS_CODE <> 'DEMH') T3
ON
	T1.UNIT_KEY = T3.UNIT_KEY 
INNER JOIN
	(SELECT BLK_KEY, EST_KEY FROM SOR_HSM_BLK) T4
ON
	T1.BLK_KEY = T4.BLK_KEY 
LEFT OUTER JOIN
	(SELECT RAS.ALCT_STD_KEY, RAS.BLK_KEY, RAS.UNIT_IFA_AREA, RAS.UNIT_TYPE_CODE, RASS.MIN_UNIT_HEAD_CNT, RASS.MAX_UNIT_HEAD_CNT FROM SOR_EMS_RFX_ALCT_STD RAS, SOR_EMS_RFX_ALCT_STD_STS RASS WHERE RAS.ALCT_STD_KEY = RASS.ALCT_STD_KEY AND UNIT_ALCT_STD_TYPE_CODE = 'O' AND ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1) - 1 BETWEEN RASS.BGN_DATE AND RASS.END_DATE) T5
ON
	T1.BLK_KEY = T5.BLK_KEY AND T1.UNIT_IFA_AREA = T5.UNIT_IFA_AREA AND T1.UNIT_TYPE_CODE = T5.UNIT_TYPE_CODE
INNER JOIN
	(SELECT D.EMMS_DSTR_KEY, EDR.EST_KEY FROM SOR_HSM_DSTR D, SOR_HSM_EST_DSTR_RLTN EDR WHERE EDR.DSTR_KEY = D.DSTR_KEY AND DSTR_TYPE_CODE = 'DCH' AND ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1) - 1 BETWEEN BGN_DATE AND END_DATE) DCH
ON
	T4.EST_KEY = DCH.EST_KEY 
INNER JOIN	
	(SELECT D.EMMS_DSTR_KEY, EDR.EST_KEY FROM SOR_HSM_DSTR D, SOR_HSM_EST_DSTR_RLTN EDR WHERE EDR.DSTR_KEY = D.DSTR_KEY AND DSTR_TYPE_CODE = 'DIS' AND ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1) - 1 BETWEEN BGN_DATE AND END_DATE) DIS
ON
	T4.EST_KEY = DIS.EST_KEY 
GROUP BY 
	T4.EST_KEY
	, T4.BLK_KEY
	, DIS.EMMS_DSTR_KEY
	, DCH.EMMS_DSTR_KEY
	, T1.UNIT_TYPE_CODE
	, T5.MIN_UNIT_HEAD_CNT
	, T5.MAX_UNIT_HEAD_CNT
	, T1.UNIT_IFA_AREA;

-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_EMS_PHA_APLY
SELECT /*+ merge(ODMS) push_pred(ODMS) */
	TO_NUMBER(SUBSTR('$$v_rpt_mth', 5, 2)) AS SYS_RPT_MTH
	, TO_NUMBER(SUBSTR('$$v_rpt_mth', 1, 4)) AS SYS_RPT_YEAR
	, HSB.EST_KEY
	, DIS.EMMS_DSTR_KEY AS DSTR_BRD_EMMS_DSTR_KEY
	, DCH.EMMS_DSTR_KEY AS DSTR_CHC_EMMS_DSTR_KEY 
	, CASE WHEN ODMS.CATG_USER_TYPE_CODE IS NULL THEN 'NA' ELSE ODMS.CATG_USER_TYPE_CODE END AS CATG_USER_TYPE_CODE
	, TAMS.REHSE_CATG_CODE
	, HSU.UNIT_TYPE_CODE
	, RAS.MIN_UNIT_HEAD_CNT
	, RAS.MAX_UNIT_HEAD_CNT
	, HSU.UNIT_IFA_AREA
	, CASE WHEN ODMS.OPR_TYPE_CODE IS NULL THEN '0' ELSE ODMS.OPR_TYPE_CODE END AS OPR_TYPE_CODE
	, TAM.TNCY_AGRMT_KEY
	, CASE WHEN TO_CHAR(INTK.RVS_INTK_DATE, 'YYYYMM') = '$$v_rpt_mth' THEN 'Y' ELSE NULL END NEW_IND
	, ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1) - 1 AS CUTOFF_DATE
FROM 
	(SELECT TNCY_AGRMT_KEY, HSE_SRVC_APLY_KEY, CUST_KEY FROM SOR_EMS_TAM_TNCY_AGRMT) TAM
INNER JOIN
	(
		SELECT 
			TAMS.TNCY_AGRMT_KEY
			, TAMS.UNIT_KEY
			, TAMS.UNIT_KEY AS MAIN_UNIT_KEY
			, TAMS.TNCY_AGRMT_CMNC_DATE
			, TAMS.TNCY_AGRMT_TM_TRMT_DATE
			, TAMS.TNCY_AGRMT_TM_STS_CODE
			, TAMS.REHSE_CATG_CODE 
		FROM 
			SOR_EMS_TAM_TNCY_AGRMT_STS TAMS
		WHERE 
			TNCY_AGRMT_TM_STS_CODE IN ('P', 'I', 'A') 
			AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN BGN_DATE AND END_DATE
	UNION
		SELECT 
			TAMS.TNCY_AGRMT_KEY
			, ADTN.UNIT_KEY
			, TAMS.UNIT_KEY AS MAIN_UNIT_KEY
			, TAMS.TNCY_AGRMT_CMNC_DATE
			, TAMS.TNCY_AGRMT_TM_TRMT_DATE
			, TAMS.TNCY_AGRMT_TM_STS_CODE
			, TAMS.REHSE_CATG_CODE 
		FROM 
			SOR_EMS_TAM_TNCY_AGRMT_STS TAMS
			, (SELECT ADTN_ROOM_KEY, UNIT_KEY, TNCY_AGRMT_KEY FROM SOR_EMS_TAM_ADTN_ROOM) ADTN
			, (SELECT ADTN_ROOM_KEY FROM SOR_EMS_TAM_ADTN_ROOM_STS WHERE ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1) - 1 BETWEEN BGN_DATE AND END_DATE) ADTS
		WHERE 
			ADTN.ADTN_ROOM_KEY = ADTS.ADTN_ROOM_KEY
			AND TAMS.TNCY_AGRMT_KEY = ADTN.TNCY_AGRMT_KEY
			AND TNCY_AGRMT_TM_STS_CODE IN ('P', 'I', 'A') 
			AND TO_DATE('$$v_snsh_date', 'YYYYMMDD') BETWEEN BGN_DATE AND END_DATE
	) TAMS
ON 
	TAM.TNCY_AGRMT_KEY = TAMS.TNCY_AGRMT_KEY 
INNER JOIN
	(SELECT UNIT_KEY, BLK_KEY, UNIT_TYPE_CODE, UNIT_IFA_AREA FROM SOR_HSM_UNIT WHERE UPPER(UNIT_ADDR_CODE) LIKE 'E9%') HSU	
ON 
	TAMS.UNIT_KEY = HSU.UNIT_KEY
INNER JOIN
	(SELECT BLK_KEY, EST_KEY FROM SOR_HSM_BLK) HSB
ON 
	HSU.BLK_KEY = HSB.BLK_KEY
LEFT OUTER JOIN
	(SELECT RAS.ALCT_STD_KEY, RAS.BLK_KEY, RAS.UNIT_IFA_AREA, RAS.UNIT_TYPE_CODE, RASS.MIN_UNIT_HEAD_CNT, RASS.MAX_UNIT_HEAD_CNT FROM SOR_EMS_RFX_ALCT_STD RAS, SOR_EMS_RFX_ALCT_STD_STS RASS WHERE RAS.ALCT_STD_KEY = RASS.ALCT_STD_KEY AND UNIT_ALCT_STD_TYPE_CODE = 'O' AND ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1) - 1 BETWEEN RASS.BGN_DATE AND RASS.END_DATE) RAS
ON 
	HSU.BLK_KEY = RAS.BLK_KEY AND HSU.UNIT_IFA_AREA = RAS.UNIT_IFA_AREA AND HSU.UNIT_TYPE_CODE = RAS.UNIT_TYPE_CODE
INNER JOIN
	(SELECT D.EMMS_DSTR_KEY, EDR.EST_KEY FROM SOR_HSM_DSTR D, SOR_HSM_EST_DSTR_RLTN EDR WHERE EDR.DSTR_KEY = D.DSTR_KEY AND DSTR_TYPE_CODE = 'DCH' AND ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1) - 1 BETWEEN BGN_DATE AND END_DATE) DCH
ON 
	HSB.EST_KEY = DCH.EST_KEY
INNER JOIN
	(SELECT D.EMMS_DSTR_KEY, EDR.EST_KEY FROM SOR_HSM_DSTR D, SOR_HSM_EST_DSTR_RLTN EDR WHERE EDR.DSTR_KEY = D.DSTR_KEY AND DSTR_TYPE_CODE = 'DIS' AND ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1) - 1 BETWEEN BGN_DATE AND END_DATE) DIS
ON 
	HSB.EST_KEY = DIS.EST_KEY 
LEFT OUTER JOIN
	(
		SELECT
			PHA.HSE_SRVC_APLY_KEY 
			, QCS.CATG_USER_TYPE_CODE
			, POS.OPR_TYPE_CODE
		FROM	
			(SELECT APLY_KEY, HSE_SRVC_APLY_KEY FROM SOR_EMS_PHA_APLY) PHA
			, (SELECT APLY_KEY, QTA_CATG_CODE, OPR_CODE FROM SOR_EMS_PHA_APLY_STS WHERE ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1) - 1 BETWEEN BGN_DATE AND END_DATE) PHS
			, (SELECT QTA_CATG_USER_KEY, QTA_CATG_CODE FROM SOR_EMS_REF_QTA_CATG_USER) QCU
			, (SELECT CATG_USER_TYPE_CODE, QTA_CATG_USER_KEY FROM SOR_EMS_REF_QTA_CATG_USER_STS WHERE ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1) - 1 BETWEEN BGN_DATE AND END_DATE AND QTA_CATG_TYPE_CODE = 'C') QCS
			, (SELECT OPR_KEY, OPR_CODE FROM SOR_EMS_POR_OPR) POR
			, (SELECT OPR_KEY, OPR_TYPE_CODE FROM SOR_EMS_POR_OPR_STS WHERE ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1) - 1 BETWEEN BGN_DATE AND END_DATE) POS
		WHERE
			PHA.APLY_KEY = PHS.APLY_KEY
			AND PHS.QTA_CATG_CODE = QCU.QTA_CATG_CODE
			AND QCU.QTA_CATG_USER_KEY = QCS.QTA_CATG_USER_KEY 
			AND POR.OPR_KEY = POS.OPR_KEY
			AND PHS.OPR_CODE = POR.OPR_CODE
	) ODMS
ON 
	TAM.HSE_SRVC_APLY_KEY = ODMS.HSE_SRVC_APLY_KEY
LEFT OUTER JOIN
	(
		SELECT
			INTK.CUST_KEY
			, INTK.HSE_SRVC_APLY_KEY
			, INTK.ALCT_UNIT_KEY
			, INTK.RVS_INTK_DATE
			, RENT.RENT_FCTR_CODE
		FROM 
			(SELECT INTK.CUST_KEY, INTK.HSE_SRVC_APLY_KEY, INTK.ALCT_UNIT_KEY, INTS.RVS_INTK_DATE, INTS.RVS_RENT_FCTR_KEY FROM SOR_EMS_PAL_PRH_INTK_SCHD INTK, SOR_EMS_PAL_PRH_INTK_SCHD_STS INTS WHERE INTK.PRH_INTK_SCHD_KEY = INTS.PRH_INTK_SCHD_KEY AND INTS.INTK_SCHD_STS_CODE IN ('DC', 'OFACPT') AND ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1) - 1 BETWEEN INTS.BGN_DATE AND INTS.END_DATE) INTK
			, (SELECT RENT_FCTR_KEY, RENT_FCTR_CODE FROM SOR_EMS_SRF_RENT_FCTR_CODE) RENT
		WHERE
			INTK.RVS_RENT_FCTR_KEY = RENT.RENT_FCTR_KEY (+)
	) INTK
ON
	TAM.CUST_KEY = INTK.CUST_KEY AND TAM.HSE_SRVC_APLY_KEY = INTK.HSE_SRVC_APLY_KEY AND TAMS.MAIN_UNIT_KEY = INTK.ALCT_UNIT_KEY
WHERE
	NOT EXISTS (
		SELECT 
			NULL
		FROM 
			(
				SELECT 
					TAMS.TNCY_AGRMT_KEY
					, TAMS.UNIT_KEY
					, TAMS.TNCY_AGRMT_TM_TRMT_DATE 
				FROM 
					SOR_EMS_TAM_TNCY_AGRMT_STS TAMS
				WHERE 
					ADD_MONTHS(TO_DATE('$$v_snsh_date', 'YYYYMMDD'), 1) - 1 BETWEEN BGN_DATE AND END_DATE
			UNION
				SELECT 
					TAMS.TNCY_AGRMT_KEY
					, ADTN.UNIT_KEY
					, TAMS.TNCY_AGRMT_TM_TRMT_DATE 
				FROM 
					SOR_EMS_TAM_TNCY_AGRMT_STS TAMS
					, (SELECT ADTN_ROOM_KEY, UNIT_KEY, TNCY_AGRMT_KEY FROM SOR_EMS_TAM_ADTN_ROOM) ADTN
					, (SELECT ADTN_ROOM_KEY FROM SOR_EMS_TAM_ADTN_ROOM_STS WHERE ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1) - 1 BETWEEN BGN_DATE AND END_DATE) ADTS
				WHERE
					ADTN.ADTN_ROOM_KEY = ADTS.ADTN_ROOM_KEY
					AND TAMS.TNCY_AGRMT_KEY = ADTN.TNCY_AGRMT_KEY
					AND ADD_MONTHS(TO_DATE('$$v_snsh_date', 'YYYYMMDD'), 1) - 1 BETWEEN BGN_DATE AND END_DATE
			) TMP
		WHERE   
			TMP.UNIT_KEY = TAMS.UNIT_KEY
			AND TAMS.TNCY_AGRMT_CMNC_DATE BETWEEN TMP.TNCY_AGRMT_TM_TRMT_DATE + 1 AND TMP.TNCY_AGRMT_TM_TRMT_DATE + 30
		);

-- [SELECT] Step: read_mplt_LKP_SOR_EMS_TAM_TNCY_AGRMT_STS
-- Connection: SOR
SELECT  
	TNCY_AGRMT_KEY as TNCY_AGRMT_KEY,
	SOR_EMS_TAM_TNCY_AGRMT_STS.TNCY_AGRMT_TM_STS_CODE as TNCY_AGRMT_TM_STS_CODE,
	SOR_EMS_TAM_TNCY_AGRMT_STS.TNCY_AGRMT_CMNC_DATE as ORIG_TNCY_AGRMT_CMNC_DATE,
	SOR_EMS_TAM_TNCY_AGRMT_STS.TNCY_AGRMT_TM_TRMT_DATE as TNCY_AGRMT_TM_TRMT_DATE
