-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_HSM_UNIT
SELECT
M1.UNIT_ADDR_CODE as UNIT_ADDR_CODE, 
M1.UNIT_KEY as UNIT_KEY,
M1.EMMS_UNIT_KEY as EMMS_UNIT_KEY,
M1.UNIT_TAKE_OVER_DATE as UNIT_TAKE_OVER_DATE,
NVL(AST.MAX_UNIT_HEAD_CNT,0) as MAX_UNIT_HEAD_CNT,
NVL(AST.MIN_UNIT_HEAD_CNT,0) as MIN_UNIT_HEAD_CNT,
M1.UNIT_IFA_AREA as UNIT_IFA_AREA,
M1.UNIT_TYPE_CODE as UNIT_TYPE_CODE,
M1.HSE_UNIT_TM_STS_CODE as HSE_UNIT_TM_STS_CODE,
M1.HSE_UNIT_TM_VOID_STS_BGN_DATE as HSE_UNIT_TM_VOID_STS_BGN_DATE
FROM (
		SELECT  
		HSU.UNIT_ADDR_CODE AS UNIT_ADDR_CODE, 
		HSU.UNIT_KEY AS UNIT_KEY ,
		HSU.EMMS_UNIT_KEY AS EMMS_UNIT_KEY,
		HPUS.UNIT_TAKE_OVER_DATE AS UNIT_TAKE_OVER_DATE,
		HSUS.HSE_UNIT_TM_STS_CODE AS HSE_UNIT_TM_STS_CODE,
		HSUS.HSE_UNIT_TM_VOID_STS_BGN_DATE AS HSE_UNIT_TM_VOID_STS_BGN_DATE,
		HSB.BLK_KEY AS BLK_KEY,
		HSUs.hse_UNIT_TYPE_CODE AS UNIT_TYPE_CODE,
		HSU.UNIT_IFA_AREA AS UNIT_IFA_AREA
		FROM    
				SOR_HSM_UNIT                HSU,
				SOR_HSM_UNIT_STS            HSUS,
				SOR_HSM_BLK                 HSB,
				SOR_EMS_HSM_BLK             EMB,
				SOR_EMS_HSM_BLK_STS         EMBS,
				SOR_EMS_HSM_PRH_UNIT_STS    HPUS
		WHERE   
		HSU.UNIT_KEY = HSUS.UNIT_KEY
		and 	HSU.UNIT_KEY = HPUS.UNIT_KEY
		AND     HSU.BLK_KEY = HSB.BLK_KEY
		AND     HSB.EMMS_BLK_KEY = EMB.BLK_BK
		AND     EMB.BLK_KEY = EMBS.BLK_KEY
		AND     (EMBS.HSE_BLK_END_DATE IS NULL
		OR       EMBS.HSE_BLK_END_DATE > ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1) - 1)
		AND     EMBS.BLK_CMPLT_DATE <= ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1) - 1
		AND     EMBS.BLK_HOVR_DATE <= ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1) - 1
		and 	add_months(to_date('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1 between HPUS.BGN_DATE and HPUS.END_DATE
		AND     ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1) - 1 BETWEEN HSUS.BGN_DATE AND HSUS.END_DATE
		AND     ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1) - 1 BETWEEN EMBS.BGN_DATE AND EMBS.END_DATE
		AND     HSUS.HSE_UNIT_TM_STS_CODE IN ('VCNT', 'OCPY', 'TOBETERM')
		AND     (HSUS.HSE_UNIT_DMLH_DATE IS NULL
		OR       HSUS.HSE_UNIT_DMLH_DATE > ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1) - 1)
--		AND     HPUS.UNIT_TAKE_OVER_DATE <= ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1) - 1
		AND     HSU.UNIT_ADDR_CODE NOT LIKE 'E9%'
)M1
LEFT OUTER JOIN
(
		 SELECT MAX_UNIT_HEAD_CNT,MIN_UNIT_HEAD_CNT,UNIT_IFA_AREA,UNIT_TYPE_CODE,
		BLK_KEY	FROM SOR_EMS_RFX_ALCT_STD A1, SOR_EMS_RFX_ALCT_STD_STS A2
		 WHERE A1.ALCT_STD_KEY=A2.ALCT_STD_KEY AND UNIT_ALCT_STD_TYPE_CODE = 'O'
		 AND     ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1) - 1 BETWEEN A2.BGN_DATE AND A2.END_DATE
)AST
ON
(
		M1.BLK_KEY = AST.BLK_KEY
AND     M1.UNIT_TYPE_CODE = AST.UNIT_TYPE_CODE
AND     M1.UNIT_IFA_AREA = AST.UNIT_IFA_AREA
);

-- [SELECT] Step: read_LKP_DSTR_EST
-- Connection: DPA
SELECT DIS.EMMS_DSTR_KEY AS DSTR_BRD_DSTR_EMMS_KEY, 
DCH.EMMS_DSTR_KEY AS DSTR_CHC_DSTR_EMMS_KEY, 
E.EST_KEY as EST_KEY, 
B.BLK_KEY as BLK_KEY, 
B.EMMS_BLK_KEY as EMMS_BLK_KEY, 
U.UNIT_ADDR_CODE as UNIT_ADDR_CODE FROM 
(select D.EMMS_DSTR_KEY, EDR.EST_KEY from SOR_HSM_DSTR D, SOR_HSM_EST_DSTR_RLTN EDR
WHERE EDR.DSTR_KEY = D.DSTR_KEY  AND DSTR_TYPE_CODE = 'DCH' 
AND add_months(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1 BETWEEN BGN_DATE AND END_DATE) DCH,
(select D.EMMS_DSTR_KEY, EDR.EST_KEY from SOR_HSM_DSTR D, SOR_HSM_EST_DSTR_RLTN EDR
WHERE EDR.DSTR_KEY = D.DSTR_KEY  AND DSTR_TYPE_CODE = 'DIS'
AND add_months(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1 BETWEEN BGN_DATE AND END_DATE) DIS,
SOR_HSM_UNIT U, 
SOR_HSM_BLK B, 
SOR_HSM_EST E
WHERE E.EST_KEY = DIS.EST_KEY 
AND E.EST_KEY = DCH.EST_KEY
AND U.BLK_KEY = B.BLK_KEY 
AND B.EST_KEY = E.EST_KEY;

