-- Table: DDS_DMNS_EMS_FLAT_TYPE
-- Connection: DPA
SELECT * FROM DDS_DMNS_EMS_FLAT_TYPE;

-- [SELECT] Step: read_LKP_DDS_DMNS_UNIT_SIZE
-- Connection: DPA
SELECT 
DDS_DMNS_UNIT_SIZE.UNIT_SIZE_DMNS_KEY as UNIT_SIZE_DMNS_KEY, 
DDS_DMNS_UNIT_SIZE.UNIT_SIZE_CODE as UNIT_SIZE_CODE, 
DDS_DMNS_UNIT_SIZE.UNIT_SIZE_DESP as UNIT_SIZE_DESP, 
DDS_DMNS_UNIT_SIZE.UNIT_SIZE_MIN_AREA as UNIT_SIZE_MIN_AREA, 
DDS_DMNS_UNIT_SIZE.UNIT_SIZE_MAX_AREA as UNIT_SIZE_MAX_AREA 
FROM DDS_DMNS_UNIT_SIZE
WHERE
UNIT_SIZE_CODE IN ('A','B','C','D','E','F','G','H','I','J');

-- [SELECT] Step: read_LKP_UNIT_ADVS_ENV_CODE_IND
-- Connection: DPA
SELECT UNIT_ADDR_CODE as UNIT_ADDR_CODE, 
DECODE( COUNT(1), 0, 'N', 'Y' ) as UNIT_ADVS_ENV_CODE_IND
FROM SOR_HSM_UNIT U, SOR_HSM_UNIT_STS US, 
SOR_EMS_HSM_UNIT_SCND_ENV E, SOR_EMS_HSM_UNIT_SCND_ENV_STS ES
WHERE U.UNIT_KEY = E.UNIT_KEY
and U.UNIT_KEY = US.UNIT_KEY
and ES.UNIT_SCND_ENV_KEY = E.UNIT_SCND_ENV_KEY
AND E.UNIT_SCND_ENV_CODE IN ( '31', '32', '33', '35', '36', '37','40', '41', '42', '43', '44', '45' )
and add_months(to_date('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1 between ES.BGN_DATE and ES.END_DATE
and add_months(to_date('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1 between US.BGN_DATE and US.END_DATE
group by UNIT_ADDR_CODE;

-- [SELECT] Step: read_LKP_SOR_EMS_SRP_MRRS_RENT_RCV
-- Connection: DPA
select SOR_EMS_SRP_MRRS_RENT_RCV.UNIT_KEY as UNIT_KEY,
nvl(SOR_EMS_SRP_MRRS_RENT_RCV.UNIT_GRS_RENT_AMT,0) as UNIT_GRS_RENT_AMT
from SOR_EMS_SRP_MRRS_RENT_RCV
where (SOR_EMS_SRP_MRRS_RENT_RCV.SYS_RPT_YEAR*100+SOR_EMS_SRP_MRRS_RENT_RCV.SYS_RPT_MTH) = to_number('$$v_rpt_mth');

-- [SELECT] Step: read_LKP_SCD_BLK_KEY
-- Connection: DPA
select distinct BLK_SCD_KEY as BLK_SCD_KEY, BLK_KEY as OUT_BLK_KEY 
FROM DDS_HRCHY_EMS_BLK
WHERE add_months(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1 BETWEEN BGN_DATE AND END_DATE;

