SELECT * FROM DDS_DMNS_EMS_DSTR_BRD_DSTR;

-- [SELECT] Step: read_LKP_DDS_HRCHY_EMS_EST
-- Connection: DPA
SELECT 
DDS_HRCHY_EMS_EST.EST_SCD_KEY as EST_SCD_KEY, 
DDS_HRCHY_EMS_EST.RGN_KEY as RGN_KEY, 
DDS_HRCHY_EMS_EST.RGN_CODE as RGN_CODE, 
DDS_HRCHY_EMS_EST.RGN_ENG_NAME as RGN_ENG_NAME, 
DDS_HRCHY_EMS_EST.MGT_DSTR_KEY as MGT_DSTR_KEY, 
DDS_HRCHY_EMS_EST.MGT_DSTR_CODE as MGT_DSTR_CODE, 
DDS_HRCHY_EMS_EST.MGT_DSTR_ENG_NAME as MGT_DSTR_ENG_NAME, 
DDS_HRCHY_EMS_EST.DTMO_KEY as DTMO_KEY, 
DDS_HRCHY_EMS_EST.DTMO_CODE as DTMO_CODE, 
DDS_HRCHY_EMS_EST.DTMO_ENG_NAME as DTMO_ENG_NAME, 
DDS_HRCHY_EMS_EST.EST_CODE as EST_CODE, 
DDS_HRCHY_EMS_EST.EST_TYPE_CODE as EST_TYPE_CODE, 
DDS_HRCHY_EMS_EST.EST_ENG_NAME as EST_ENG_NAME, 
DDS_HRCHY_EMS_EST.EST_CHI_NAME as EST_CHI_NAME, 
DDS_HRCHY_EMS_EST.BGN_DATE as BGN_DATE, 
DDS_HRCHY_EMS_EST.END_DATE as END_DATE, DDS_HRCHY_EMS_EST.EST_KEY as EST_KEY 
FROM DDS_HRCHY_EMS_EST
WHERE add_months(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1 between DDS_HRCHY_EMS_EST.BGN_DATE AND DDS_HRCHY_EMS_EST.END_DATE;

-- [SELECT] Step: read_LKP_DDS_HRCHY_EMS_DSTR_CHC_DSTR
-- Connection: DPA
SELECT DDS_HRCHY_EMS_DSTR_CHC_DSTR.DSTR_CHC_DSTR_SCD_KEY as DSTR_CHC_DSTR_SCD_KEY, DDS_HRCHY_EMS_DSTR_CHC_DSTR.DSTR_CHC_DSTR_CODE as DSTR_CHC_DSTR_CODE, DDS_HRCHY_EMS_DSTR_CHC_DSTR.DSTR_CHC_DSTR_ENG_NAME as DSTR_CHC_DSTR_ENG_NAME, DDS_HRCHY_EMS_DSTR_CHC_DSTR.EMMS_DSTR_KEY as EMMS_DSTR_KEY, DDS_HRCHY_EMS_DSTR_CHC_DSTR.DSTR_CHC_SBDSTR_CODE as DSTR_CHC_SBDSTR_CODE, DDS_HRCHY_EMS_DSTR_CHC_DSTR.DSTR_CHC_SBDSTR_ENG_NAME as DSTR_CHC_SBDSTR_ENG_NAME, DDS_HRCHY_EMS_DSTR_CHC_DSTR.BGN_DATE as BGN_DATE, DDS_HRCHY_EMS_DSTR_CHC_DSTR.END_DATE as END_DATE, DDS_HRCHY_EMS_DSTR_CHC_DSTR.EMMS_SBDSTR_KEY as EMMS_SBDSTR_KEY FROM DDS_HRCHY_EMS_DSTR_CHC_DSTR
WHERE add_months(to_date('$$v_rpt_mth'||'01', 'YYYYMMDD'),1)-1 between DDS_HRCHY_EMS_DSTR_CHC_DSTR.BGN_DATE and DDS_HRCHY_EMS_DSTR_CHC_DSTR.END_DATE;

-- [SELECT] Step: read_mplt_LKPTRANS
-- Connection: source_db
SELECT 
	SOR_HSM_EST.EST_KEY AS EST_KEY, 
	case when max(MGT_TYPE_CODE) <= 0 and min(MGT_TYPE_CODE) = -1 then 'PSA'
	when min(MGT_TYPE_CODE) >= 0 and max(MGT_TYPE_CODE) = 1  then 'HA'
	when max(MGT_TYPE_CODE) = 0  and min(MGT_TYPE_CODE) = 0   then 'N/A'
	else 'MIXED' end AS MGT_MODE_CODE
FROM
	SOR_HSM_EST, 
	(SELECT DISTINCT SOR_HSM_BLK.EST_KEY, SOR_EMS_HSM_PRH_BLK_STS.BLK_KEY AS BLK_KEY, 
	DECODE(SOR_EMS_HSM_PRH_BLK_STS.MGT_TYPE_CODE, NULL, 0, 'HD', 1, -1) AS MGT_TYPE_CODE
	FROM
		SOR_HSM_BLK,
		SOR_EMS_HSM_PRH_BLK_STS
	WHERE
		ADD_MONTHS(TO_DATE('$$v_rpt_mth'||'01', 'YYYYMMDD'), 1)-1 BETWEEN SOR_EMS_HSM_PRH_BLK_STS.BGN_DATE AND SOR_EMS_HSM_PRH_BLK_STS.END_DATE		
		AND SOR_HSM_BLK.BLK_KEY=SOR_EMS_HSM_PRH_BLK_STS.BLK_KEY) MGT_TYPE
WHERE
	SOR_HSM_EST.EST_KEY=MGT_TYPE.EST_KEY
GROUP BY
	SOR_HSM_EST.EST_KEY;

