-- [SELECT] Step: read_LKP_SOR_EMS_HSM_PRH_UNIT_STS
-- Connection: SOR
SELECT 
STS.UNIT_KEY AS UNIT_KEY, STS.BGN_DATE AS BGN_DATE, 
STS.END_DATE AS END_DATE, STS.UNIT_HSC_TYPE_CODE AS UNIT_HSC_TYPE_CODE 
FROM SOR_EMS_HSM_PRH_UNIT_STS STS 
WHERE LAST_DAY(TO_DATE($$v_rpt_mth||'01','YYYYMMDD')) BETWEEN STS.BGN_DATE AND STS.END_DATE AND STS.UNIT_HSC_TYPE_CODE IS NOT NULL;

-- [SELECT] Step: read_LKP_DDS_DMNS_EMS_HSC_UNIT_TYPE
-- Connection: DPA
SELECT 
TYPE.HSC_UNIT_TYPE_DMNS_KEY AS HSC_UNIT_TYPE_DMNS_KEY, 
TYPE.HSC_UNIT_TYPE_CODE AS HSC_UNIT_TYPE_CODE 
FROM DDS_DMNS_EMS_HSC_UNIT_TYPE TYPE 
WHERE HSC_UNIT_TYPE_SCHM_CODE = 'TYP123';

-- [SELECT] Step: read_LKPTRANS
-- Connection: SSA
SELECT
  'E'||RPAD(TRIM(eis.ESTATE), 4, ' ') || LPAD(TRIM(eis.BLOCK), 3, ' ') || LPAD(TRIM(eis.UNIT), 5, ' ') || NVL(eis.CON_REF, ' ') || NVL(eis.SHRIND, ' ') as UNIT_ADDR_CODE,
  VCNT_IND as VCNT_IND
FROM
  EIS_HA_PRH_RNTL_UNIT eis
WHERE
  VCNT_IND is not null;

